window.KhaemenesScience9CumulativeQuestionBank=[{"unit":"Unit 00","domain":"Safety","prompt":"A planned investigation has a serious risk that cannot be controlled with available equipment. What should happen first?","options":["Revise or replace the method before beginning.","Proceed with fewer trials.","Ask participants to accept the risk.","Continue if the scientific question is important."],"answer":0,"explanation":"An investigation must not begin until serious risks are removed or reasonably controlled.","id":"legacy-q001","source":"unit-00","difficulty":"cumulative","type":"evidence"},{"unit":"Unit 00","domain":"Personal protection","prompt":"Which action is appropriate when an approved activity requires splash goggles?","options":["Share one pair while materials are being handled.","Wear correctly fitting splash goggles for the entire exposure period.","Wear ordinary eyeglasses instead.","Remove the goggles whenever they fog."],"answer":1,"explanation":"Required protective equipment must be correctly fitted and worn throughout the relevant activity.","id":"legacy-q002","source":"unit-00","difficulty":"cumulative","type":"concept"},{"unit":"Unit 00","domain":"Chemical habits","prompt":"What is the safest rule for an unlabeled substance?","options":["Taste a tiny amount.","Mix it with water to see what happens.","Do not handle or use it; inform the supervising adult.","Smell it closely to identify it."],"answer":2,"explanation":"Unknown and unlabeled substances must be treated as potentially hazardous.","id":"legacy-q003","source":"unit-00","difficulty":"cumulative","type":"concept"},{"unit":"Unit 00","domain":"Emergency response","prompt":"A liquid splashes into a student’s eye during a supervised laboratory activity. What is the correct immediate response?","options":["Finish recording data before responding.","Rub the eye with a dry towel.","Wait to see whether pain develops.","Use the approved eyewash procedure immediately and alert the supervisor."],"answer":3,"explanation":"Immediate flushing and adult notification are required; treatment must not be delayed.","id":"legacy-q004","source":"unit-00","difficulty":"cumulative","type":"concept"},{"unit":"Unit 00","domain":"Data integrity","prompt":"A result does not match the other trials. What is the most responsible response?","options":["Document it, check the method and equipment, and repeat if appropriate.","Delete it without explanation.","Change it to equal the mean.","Conclude that all other trials are wrong."],"answer":0,"explanation":"Unexpected data should be investigated and reported transparently.","id":"legacy-q005","source":"unit-00","difficulty":"cumulative","type":"evidence"},{"unit":"Unit 00","domain":"Ethics","prompt":"Which study plan requires informed consent and additional ethical safeguards?","options":["Timing a paper helicopter.","Collecting identifiable health information from human participants.","Measuring the length of classroom pencils.","Using a published anonymous dataset."],"answer":1,"explanation":"Identifiable human data require consent, privacy protection, and appropriate oversight.","id":"legacy-q006","source":"unit-00","difficulty":"cumulative","type":"evidence"},{"unit":"Unit 00","domain":"Environmental responsibility","prompt":"Which field practice is appropriate?","options":["Remove rare specimens for a personal collection.","Publish exact locations of vulnerable species.","Observe from a permitted stable location and minimize disturbance.","Enter a protected nesting area for a closer photograph."],"answer":2,"explanation":"Safe scientific observation protects habitats, organisms, cultural resources, and sensitive locations.","id":"legacy-q007","source":"unit-00","difficulty":"cumulative","type":"concept"},{"unit":"Unit 00","domain":"Scientific habits","prompt":"Which notebook entry best supports reproducibility?","options":["Only the final conclusion.","A copied procedure with no changes recorded.","A list of results without units.","Date, materials, exact method, measurements, changes, and unexpected events."],"answer":3,"explanation":"Reproducibility requires a transparent record of what was actually done and observed.","id":"legacy-q008","source":"unit-00","difficulty":"cumulative","type":"concept"},{"unit":"Unit 01","domain":"Variables","prompt":"A student changes light intensity and measures the oxygen production rate of an aquatic plant. What is the independent variable?","options":["Light intensity.","Oxygen production rate.","Plant species.","Elapsed measurement time."],"answer":0,"explanation":"The independent variable is deliberately changed.","id":"legacy-q009","source":"unit-01","difficulty":"cumulative","type":"concept"},{"unit":"Unit 01","domain":"Measurement","prompt":"Repeated measurements are 12.2 cm, 12.2 cm, 12.3 cm, and 12.2 cm. What can be concluded from these values alone?","options":["There is no measurement uncertainty.","The measurements are precise.","The measurements are accurate.","The true value is 12.225 cm."],"answer":1,"explanation":"Closely grouped values show precision; accuracy requires comparison with a trusted value.","id":"legacy-q010","source":"unit-01","difficulty":"cumulative","type":"quantitative"},{"unit":"Unit 01","domain":"Data processing","prompt":"What is the mean of 4.0, 4.5, 5.0, and 4.5 seconds?","options":["4.75 seconds.","18.0 seconds.","4.5 seconds.","4.0 seconds."],"answer":2,"explanation":"The sum is 18.0 seconds and 18.0 ÷ 4 = 4.5 seconds.","id":"legacy-q011","source":"unit-01","difficulty":"cumulative","type":"quantitative"},{"unit":"Unit 01","domain":"Graphs","prompt":"Which graph is generally most suitable for showing the relationship between temperature and reaction rate?","options":["A pie chart.","A pictogram.","A single-category bar chart.","A scatter plot or line graph with two numerical axes."],"answer":3,"explanation":"Both variables are quantitative, so paired numerical axes are appropriate.","id":"legacy-q012","source":"unit-01","difficulty":"cumulative","type":"concept"},{"unit":"Unit 01","domain":"Reliability","prompt":"Why are repeated trials useful?","options":["They reveal variation and improve confidence in an estimate such as the mean.","They prove the hypothesis.","They remove all random error.","They guarantee accuracy."],"answer":0,"explanation":"Repeats show variability and strengthen estimates but do not guarantee correctness.","id":"legacy-q013","source":"unit-01","difficulty":"cumulative","type":"evidence"},{"unit":"Unit 01","domain":"Causation","prompt":"An observational study finds an association between screen time and sleep duration. Which conclusion is justified?","options":["No confounding variable could exist.","The variables were associated in the observed sample, but causation is not established.","Screen time caused every sleep difference.","Sleep duration caused all screen use."],"answer":1,"explanation":"Observational association alone does not establish a causal mechanism.","id":"legacy-q014","source":"unit-01","difficulty":"cumulative","type":"evidence"},{"unit":"Unit 01","domain":"Claim-evidence-reasoning","prompt":"Which statement is scientific reasoning rather than a claim or a measurement?","options":["The reaction lasted 24 seconds.","Three trials were completed.","Greater surface area increases collision opportunities, explaining the faster measured reaction.","The powdered sample reacted faster."],"answer":2,"explanation":"Reasoning connects evidence to a claim through a scientific principle.","id":"legacy-q015","source":"unit-01","difficulty":"cumulative","type":"evidence"},{"unit":"Unit 01","domain":"Uncertainty","prompt":"A ruler has millimetre markings. Which report best reflects its resolution for a direct length reading?","options":["Report twenty decimal places.","Report no units.","Claim the length is exact.","Report to the nearest millimetre and acknowledge reading uncertainty."],"answer":3,"explanation":"The reporting precision should match the instrument resolution and method.","id":"legacy-q016","source":"unit-01","difficulty":"cumulative","type":"evidence"},{"unit":"Unit 02","domain":"Cell theory","prompt":"Which statement is part of modern cell theory?","options":["All living organisms consist of one or more cells.","Every cell has a nucleus.","Viruses are complete cells.","Cells arise only from nonliving matter."],"answer":0,"explanation":"Cell theory identifies cells as the basic units of living systems.","id":"legacy-q017","source":"unit-02","difficulty":"cumulative","type":"concept"},{"unit":"Unit 02","domain":"Cell structures","prompt":"Which structures occur in all known cells?","options":["A Golgi apparatus and lysosomes.","A plasma membrane and ribosomes.","A nucleus and mitochondria.","Chloroplasts and a cell wall."],"answer":1,"explanation":"All cells require a boundary membrane and ribosomes for protein synthesis.","id":"legacy-q018","source":"unit-02","difficulty":"cumulative","type":"model"},{"unit":"Unit 02","domain":"Classification","prompt":"Which feature distinguishes a typical eukaryotic cell from a typical prokaryotic cell?","options":["It has a plasma membrane.","It contains genetic material.","Most DNA is enclosed in a membrane-bound nucleus.","It has ribosomes."],"answer":2,"explanation":"Typical eukaryotes have a nucleus; prokaryotes do not.","id":"legacy-q019","source":"unit-02","difficulty":"cumulative","type":"concept"},{"unit":"Unit 02","domain":"Microscopy","prompt":"A specimen is 0.04 mm long and its image is 20 mm long. What is the magnification?","options":["50×.","800×.","0.002×.","500×."],"answer":3,"explanation":"Magnification = image size ÷ actual size = 20 ÷ 0.04 = 500.","id":"legacy-q020","source":"unit-02","difficulty":"cumulative","type":"quantitative"},{"unit":"Unit 02","domain":"Transport","prompt":"Osmosis is the net movement of:","options":["Water across a selectively permeable membrane from higher water potential toward lower water potential.","Solute from low concentration to high concentration without energy.","All particles through any membrane.","Water only from low solute concentration to low solute concentration."],"answer":0,"explanation":"Osmosis is a specific water-transport process across a selectively permeable membrane.","id":"legacy-q021","source":"unit-02","difficulty":"cumulative","type":"concept"},{"unit":"Unit 02","domain":"Surface area","prompt":"Why does a high surface-area-to-volume ratio support exchange?","options":["It prevents all water movement.","More membrane area is available relative to the material requiring exchange.","It eliminates diffusion distance.","It creates energy."],"answer":1,"explanation":"Greater relative surface area can increase exchange capacity.","id":"legacy-q022","source":"unit-02","difficulty":"cumulative","type":"concept"},{"unit":"Unit 02","domain":"Energy and matter","prompt":"Which statement correctly links photosynthesis and cellular respiration?","options":["Respiration occurs only in animals.","Photosynthesis destroys carbon atoms.","Photosynthesis stores energy in organic molecules, while respiration transfers usable energy from those molecules.","Both processes require sunlight at every step."],"answer":2,"explanation":"The processes connect matter cycling with energy transformation.","id":"legacy-q023","source":"unit-02","difficulty":"cumulative","type":"model"},{"unit":"Unit 02","domain":"Organization","prompt":"Which sequence is ordered from smaller to larger biological organization?","options":["Organ → cell → tissue → organism.","Tissue → organ system → cell → organ.","Organ system → organ → tissue → cell.","Cell → tissue → organ → organ system."],"answer":3,"explanation":"Specialized cells form tissues, tissues form organs, and organs work in systems.","id":"legacy-q024","source":"unit-02","difficulty":"cumulative","type":"model"},{"unit":"Unit 03","domain":"Homeostasis","prompt":"Homeostasis is best described as:","options":["Dynamic regulation of internal conditions within functional ranges.","Keeping every variable perfectly constant.","A process occurring only during illness.","The absence of environmental change."],"answer":0,"explanation":"Homeostatic systems continuously adjust rather than maintaining exact fixed values.","id":"legacy-q025","source":"unit-03","difficulty":"cumulative","type":"model"},{"unit":"Unit 03","domain":"Feedback","prompt":"Which sequence represents a negative-feedback system?","options":["Stimulus → random action with no information pathway.","Change → receptor → coordinating centre → effector → response that reduces the change.","Change → amplifier → response that increases the change indefinitely.","Effector → receptor → no response."],"answer":1,"explanation":"Negative feedback opposes a deviation from a regulated range.","id":"legacy-q026","source":"unit-03","difficulty":"cumulative","type":"model"},{"unit":"Unit 03","domain":"Circulation","prompt":"What is the primary role of red blood cells?","options":["Filter urine.","Transmit nerve impulses.","Transport oxygen using haemoglobin.","Produce digestive enzymes."],"answer":2,"explanation":"Haemoglobin in red blood cells binds and transports oxygen.","id":"legacy-q027","source":"unit-03","difficulty":"cumulative","type":"concept"},{"unit":"Unit 03","domain":"Gas exchange","prompt":"Which adaptation increases gas-exchange efficiency in alveoli?","options":["Thick dry walls.","Low blood supply.","A small number of sealed chambers.","Large surface area and a thin exchange barrier."],"answer":3,"explanation":"A large area, short diffusion path, and maintained gradients support diffusion.","id":"legacy-q028","source":"unit-03","difficulty":"cumulative","type":"concept"},{"unit":"Unit 03","domain":"Digestion","prompt":"Most absorption of digested nutrients occurs in the:","options":["Small intestine.","Stomach.","Large intestine.","Oesophagus."],"answer":0,"explanation":"The small intestine has a large absorptive surface and rich transport network.","id":"legacy-q029","source":"unit-03","difficulty":"cumulative","type":"concept"},{"unit":"Unit 03","domain":"Excretion","prompt":"The kidneys help regulate:","options":["Only food intake.","Water, ions, pH, and removal of nitrogenous wastes.","Only body temperature.","Only oxygen uptake."],"answer":1,"explanation":"Kidneys filter blood and adjust the composition of body fluids.","id":"legacy-q030","source":"unit-03","difficulty":"cumulative","type":"concept"},{"unit":"Unit 03","domain":"Coordination","prompt":"Compared with endocrine signalling, nervous signalling is generally:","options":["Carried only in blood.","Unable to affect muscles.","Faster and more targeted.","Always slower and more widespread."],"answer":2,"explanation":"Nervous impulses act rapidly through specific pathways; hormones often act more slowly.","id":"legacy-q031","source":"unit-03","difficulty":"cumulative","type":"concept"},{"unit":"Unit 03","domain":"Health data ethics","prompt":"A classroom heart-rate record should be used to:","options":["Diagnose heart disease.","Publish named student records.","Replace professional medical evaluation.","Explore physiological patterns without diagnosing a medical condition."],"answer":3,"explanation":"Educational measurements require privacy and cannot support diagnosis.","id":"legacy-q032","source":"unit-03","difficulty":"cumulative","type":"evidence"},{"unit":"Unit 04","domain":"Genetic organization","prompt":"Which sequence is correct?","options":["DNA contains genes and is organized into chromosomes.","Chromosomes contain cells inside genes.","Genes contain organisms.","Alleles are made of tissues."],"answer":0,"explanation":"Genes are DNA sequences located on chromosomes.","id":"legacy-q033","source":"unit-04","difficulty":"cumulative","type":"model"},{"unit":"Unit 04","domain":"Mitosis","prompt":"Mitosis usually produces:","options":["Gametes only.","Two genetically similar daughter cells with the same chromosome number as the parent cell.","Four genetically varied haploid cells.","One cell with twice the chromosome number."],"answer":1,"explanation":"Mitosis supports growth, repair, and many forms of asexual reproduction.","id":"legacy-q034","source":"unit-04","difficulty":"cumulative","type":"concept"},{"unit":"Unit 04","domain":"Meiosis","prompt":"Meiosis contributes to variation through:","options":["Preventing chromosome separation.","Eliminating all mutation.","Crossing over, independent assortment, and random fertilization.","Producing identical diploid cells."],"answer":2,"explanation":"Meiosis and fertilization reshuffle inherited information.","id":"legacy-q035","source":"unit-04","difficulty":"cumulative","type":"concept"},{"unit":"Unit 04","domain":"Probability","prompt":"For Aa × Aa, what is the expected probability of genotype aa?","options":["1/2.","3/4.","1.","1/4."],"answer":3,"explanation":"The genotype ratio is 1 AA : 2 Aa : 1 aa.","id":"legacy-q036","source":"unit-04","difficulty":"cumulative","type":"quantitative"},{"unit":"Unit 04","domain":"Phenotype","prompt":"Phenotype is influenced by:","options":["Genotype and environmental conditions.","Genotype only in every trait.","Environment only in every trait.","Neither inheritance nor environment."],"answer":0,"explanation":"Trait expression commonly reflects both inherited information and environment.","id":"legacy-q037","source":"unit-04","difficulty":"cumulative","type":"concept"},{"unit":"Unit 04","domain":"Mutation","prompt":"A mutation is:","options":["A change in exercise level.","A change in genetic material that may be neutral, harmful, or beneficial depending on context.","Always harmful.","Always inherited by offspring."],"answer":1,"explanation":"Mutation effects depend on location, cell type, environment, and biological context.","id":"legacy-q038","source":"unit-04","difficulty":"cumulative","type":"concept"},{"unit":"Unit 04","domain":"Cell cycle","prompt":"Why is cell-cycle regulation important?","options":["It stops all cell replacement.","It produces gametes by mitosis.","It coordinates division and helps limit uncontrolled proliferation.","It guarantees that cancer cannot occur."],"answer":2,"explanation":"Checkpoints and regulatory systems reduce inappropriate division but are not perfect.","id":"legacy-q039","source":"unit-04","difficulty":"cumulative","type":"model"},{"unit":"Unit 04","domain":"Genetic ethics","prompt":"Which principle is essential when using identifiable genetic information?","options":["Public release without permission.","Treating probability as destiny.","Using ancestry claims to rank human worth.","Consent, privacy, limited access, and recognition of uncertainty."],"answer":3,"explanation":"Genetic data are sensitive and must not be used deterministically or discriminatorily.","id":"legacy-q040","source":"unit-04","difficulty":"cumulative","type":"evidence"},{"unit":"Unit 05","domain":"Ecological organization","prompt":"Which term describes all populations of different species living and interacting in an area?","options":["Community.","Population.","Habitat.","Organism."],"answer":0,"explanation":"A community contains interacting populations of multiple species.","id":"legacy-q041","source":"unit-05","difficulty":"cumulative","type":"model"},{"unit":"Unit 05","domain":"Energy flow","prompt":"Why is less energy available at higher trophic levels?","options":["Matter stops cycling.","Organisms use and dissipate much energy through metabolism and heat transfer.","Energy atoms are destroyed.","Predators cannot digest food."],"answer":1,"explanation":"Energy is transferred and dissipated, so only part enters the next trophic level.","id":"legacy-q042","source":"unit-05","difficulty":"cumulative","type":"model"},{"unit":"Unit 05","domain":"Population ecology","prompt":"A population exceeds resource availability and then declines. Which factor most directly explains the decline?","options":["Creation of new energy.","Removal of all variation.","Density-dependent limitation such as competition for food.","Unlimited carrying capacity."],"answer":2,"explanation":"Competition, disease, and predation can intensify as density rises.","id":"legacy-q043","source":"unit-05","difficulty":"cumulative","type":"concept"},{"unit":"Unit 05","domain":"Biodiversity","prompt":"Species richness measures:","options":["The total biomass only.","The genetic sequence of one organism.","The age of an ecosystem.","The number of species present."],"answer":3,"explanation":"Richness counts species, while evenness describes relative abundances.","id":"legacy-q044","source":"unit-05","difficulty":"cumulative","type":"concept"},{"unit":"Unit 05","domain":"Natural selection","prompt":"Natural selection requires:","options":["Heritable variation and differences in reproductive success.","Individuals changing genes because they need to.","All organisms surviving equally.","No environmental influence."],"answer":0,"explanation":"Population traits change across generations when inherited variants affect reproductive success.","id":"legacy-q045","source":"unit-05","difficulty":"cumulative","type":"concept"},{"unit":"Unit 05","domain":"Evidence for evolution","prompt":"Which is direct empirical evidence used to reconstruct evolutionary relationships?","options":["The assumption that all similarities have one cause.","DNA sequence similarities and differences.","A philosophical preference.","A single unsupported story."],"answer":1,"explanation":"Genetic data are measured evidence; ancestry remains an inference supported by multiple evidence lines.","id":"legacy-q046","source":"unit-05","difficulty":"cumulative","type":"evidence"},{"unit":"Unit 05","domain":"Ecosystem resilience","prompt":"An ecosystem is generally more resilient when it has:","options":["No disturbance history.","No nutrient cycling.","Functional diversity and multiple pathways that can maintain processes.","Only one species performing each function."],"answer":2,"explanation":"Redundancy and diversity can support recovery, though resilience remains context-dependent.","id":"legacy-q047","source":"unit-05","difficulty":"cumulative","type":"model"},{"unit":"Unit 05","domain":"Conservation","prompt":"Which plan is strongest?","options":["Move organisms without permits.","Publish sensitive nest locations.","Choose an action without baseline data.","Protect habitat, involve affected communities, monitor outcomes, and revise using evidence."],"answer":3,"explanation":"Effective conservation combines ecological evidence, legal and cultural safeguards, monitoring, and adaptation.","id":"legacy-q048","source":"unit-05","difficulty":"cumulative","type":"model"},{"unit":"Unit 06","domain":"Atomic identity","prompt":"The atomic number equals the number of:","options":["Protons.","Neutrons plus electrons.","Neutrons only.","Electron shells."],"answer":0,"explanation":"Element identity is determined by proton number.","id":"legacy-q049","source":"unit-06","difficulty":"cumulative","type":"concept"},{"unit":"Unit 06","domain":"Particle counts","prompt":"A neutral atom has atomic number 12. How many electrons does it have?","options":["10.","12.","6.","24."],"answer":1,"explanation":"A neutral atom has equal numbers of protons and electrons.","id":"legacy-q050","source":"unit-06","difficulty":"cumulative","type":"quantitative"},{"unit":"Unit 06","domain":"Isotopes","prompt":"Isotopes of the same element differ in their number of:","options":["Valence shells only.","Nuclei.","Neutrons.","Protons."],"answer":2,"explanation":"Isotopes share proton number but have different neutron counts.","id":"legacy-q051","source":"unit-06","difficulty":"cumulative","type":"concept"},{"unit":"Unit 06","domain":"Ions","prompt":"An atom with 17 protons and 18 electrons has charge:","options":["+1.","0.","−17.","−1."],"answer":3,"explanation":"One extra electron gives a net charge of −1.","id":"legacy-q052","source":"unit-06","difficulty":"cumulative","type":"concept"},{"unit":"Unit 06","domain":"Relative atomic mass","prompt":"Why is a periodic-table atomic mass often not a whole number?","options":["It is an abundance-weighted average of naturally occurring isotopes.","Atoms contain fractional protons.","Every isotope has the same abundance.","Electrons have no mass."],"answer":0,"explanation":"The reported value reflects isotope masses and their relative abundance.","id":"legacy-q053","source":"unit-06","difficulty":"cumulative","type":"concept"},{"unit":"Unit 06","domain":"Electron arrangement","prompt":"For elements 1–20, group patterns are strongly related to:","options":["The number of compounds already discovered.","Outer-electron arrangements.","Neutron color.","Nuclear size only."],"answer":1,"explanation":"Recurring valence-electron patterns help explain chemical trends.","id":"legacy-q054","source":"unit-06","difficulty":"cumulative","type":"concept"},{"unit":"Unit 06","domain":"Periodic trends","prompt":"Which broad statement is accurate?","options":["Halogens are metals.","All elements in a period have identical properties.","Group 1 metals generally become more reactive down the group.","Noble gases are highly reactive."],"answer":2,"explanation":"Outer electrons are farther from the nucleus and more shielded down Group 1.","id":"legacy-q055","source":"unit-06","difficulty":"cumulative","type":"model"},{"unit":"Unit 06","domain":"Atomic models","prompt":"Why have atomic models changed over time?","options":["Atoms changed their laws.","Scientists preferred more complex drawings.","No experiments were involved.","New evidence required revision of earlier explanations."],"answer":3,"explanation":"Scientific models are revised when new observations are not adequately explained.","id":"legacy-q056","source":"unit-06","difficulty":"cumulative","type":"model"},{"id":"u01-q-q01","domain":"Questions","prompt":"Which question is directly investigable with measurements and a defined comparison?","options":["How does wing length in centimeters affect flight distance in meters for airplanes made from the same paper and design?","Should everyone enjoy building paper airplanes?","Is flight interesting?","Which paper airplane looks best?"],"answer":0,"explanation":"The question identifies a measurable changed variable, measurable outcome, and a comparison that can be investigated.","source":"unit-01","difficulty":"core","unit":"Unit 01","originalSource":"quiz","type":"concept"},{"id":"u01-q-q02","domain":"Variables","prompt":"A student deliberately changes ramp height and measures how far the same toy car travels. Which statement is correct?","options":["Ramp height is the dependent variable.","Distance traveled is the dependent variable.","The toy car is the independent variable.","Distance traveled should be controlled."],"answer":1,"explanation":"Distance traveled is the measured response; ramp height is deliberately changed.","source":"unit-01","difficulty":"core","unit":"Unit 01","originalSource":"quiz","type":"concept"},{"id":"u01-q-q03","domain":"Definitions","prompt":"Which is the strongest operational definition of plant growth for a two-week investigation?","options":["Growth is whatever difference the observer notices.","Growth means the plant looks healthier.","Growth is the change in stem height, measured in centimeters from the same reference point on Day 1 and Day 14.","Growth means doing well."],"answer":2,"explanation":"An operational definition states exactly how the variable is measured so another investigator can reproduce it.","source":"unit-01","difficulty":"core","unit":"Unit 01","originalSource":"quiz","type":"concept"},{"id":"u01-q-q04","domain":"Design","prompt":"Why are repeated trials useful in a fair test?","options":["They remove systematic bias automatically.","They make controlled variables unnecessary.","They guarantee the prediction is correct.","They characterize variation and provide more evidence about the typical result."],"answer":3,"explanation":"Replication helps reveal random variation and estimate a typical result, but it does not automatically correct systematic bias.","source":"unit-01","difficulty":"core","unit":"Unit 01","originalSource":"quiz","type":"evidence"},{"id":"u01-q-q05","domain":"Measurement","prompt":"A ruler has millimeter markings. Which report best respects the instrument rather than inventing unsupported precision?","options":["A length reported at a precision defensible from the ruler and measurement procedure.","Only the word 'long.'","Any number without a unit.","A length with many extra decimal places because a calculator can display them."],"answer":0,"explanation":"Reported precision should be supported by the measuring instrument and procedure, not by calculator display digits.","source":"unit-01","difficulty":"core","unit":"Unit 01","originalSource":"quiz","type":"quantitative"},{"id":"u01-q-q06","domain":"Measurement","prompt":"Four measurements are 9.8 cm, 9.8 cm, 9.9 cm, and 9.8 cm. What can be concluded from these values alone?","options":["They establish causation.","They are highly precise, but accuracy cannot be established without an appropriate reference.","They are definitely accurate.","They prove the instrument has no systematic bias."],"answer":1,"explanation":"The values cluster closely, indicating precision. Accuracy and systematic bias require additional evidence or reference checks.","source":"unit-01","difficulty":"core","unit":"Unit 01","originalSource":"quiz","type":"quantitative"},{"id":"u01-q-q07","domain":"Data integrity","prompt":"One recorded trial is far from the others. What is the strongest first response?","options":["Delete it because it weakens the pattern.","Replace it with the mean.","Preserve it, inspect the procedure and notes for a documented cause, and repeat only according to a defensible rule.","Use it as the only result because unusual data are always most important."],"answer":2,"explanation":"An unusual observation remains part of the audit trail unless a scientifically justified, documented analysis rule supports different treatment.","source":"unit-01","difficulty":"core","unit":"Unit 01","originalSource":"quiz","type":"evidence"},{"id":"u01-q-q08","domain":"Graphing","prompt":"Paper type is categorical and mean water absorbed is numerical. Which display is generally appropriate for comparing the paper categories?","options":["A line graph that implies paper types occur in a continuous sequence.","A pie chart of unrelated totals.","An unlabeled graph with no units.","A bar chart with paper type on the x-axis and clearly identified mean water absorbed on the y-axis."],"answer":3,"explanation":"A bar chart can compare a numerical summary across discrete categories; raw trials should remain available to show the basis of the summary.","source":"unit-01","difficulty":"core","unit":"Unit 01","originalSource":"quiz","type":"concept"},{"id":"u01-q-q09","domain":"Graph integrity","prompt":"Two graphs use the same data but different y-axis ranges. Which statement is most scientifically defensible?","options":["Axis range can change visual impression without changing the underlying numbers, so scale and labels must be inspected.","All graphs must begin every numerical axis at zero regardless of purpose.","Axis choices do not affect interpretation.","The graph with the steepest-looking pattern is automatically more truthful."],"answer":0,"explanation":"Scale changes visual emphasis. Readers need the axis values and context to judge magnitude honestly.","source":"unit-01","difficulty":"core","unit":"Unit 01","originalSource":"quiz","type":"evidence"},{"id":"u01-q-q10","domain":"Study types","prompt":"Researchers record students' existing sleep duration and test scores without assigning sleep schedules. What does the design directly establish?","options":["A controlled causal effect of sleep duration.","An observational relationship that may be associated but can contain confounding or reverse-causation explanations.","That test scores cause sleep duration.","That no scientific conclusion is possible."],"answer":1,"explanation":"Because sleep was observed rather than assigned, the study can examine association but does not by itself isolate a causal effect.","source":"unit-01","difficulty":"core","unit":"Unit 01","originalSource":"quiz","type":"evidence"},{"id":"u01-q-q11","domain":"Causal reasoning","prompt":"Ice-cream sales and sunburn cases both rise during hot summer periods. Which is a plausible confounding explanation?","options":["Ice cream must cause sunburn.","Sunburn must cause ice-cream purchases.","Hot sunny weather can increase both ice-cream purchases and sun exposure.","Any correlation proves both variables are inaccurate."],"answer":2,"explanation":"A third variable—hot sunny weather—can plausibly influence both observed variables.","source":"unit-01","difficulty":"core","unit":"Unit 01","originalSource":"quiz","type":"evidence"},{"id":"u01-q-q12","domain":"CER","prompt":"Which statement best describes scientific reasoning in a CER?","options":["It is a personal opinion about whether the result is interesting.","It lists sources without connecting them to the claim.","It repeats the evidence using different words.","It explains why the evidence bears on the claim using relevant scientific ideas, study design, and appropriate limitations."],"answer":3,"explanation":"Reasoning supplies the logical and scientific connection between evidence and claim and should respect design limitations.","source":"unit-01","difficulty":"core","unit":"Unit 01","originalSource":"quiz","type":"concept"},{"id":"u01-q-q13","domain":"Sources","prompt":"A news headline makes a strong scientific claim. What is the strongest source-literacy response?","options":["Trace the claim toward the original study, dataset, or agency report and compare the original evidence and limitations with the headline wording.","Reject every news report automatically.","Count how many times the claim was reposted.","Trust the headline if it sounds scientific."],"answer":0,"explanation":"Tracing toward original evidence allows the reader to inspect method, scope, limitations, and whether the public wording preserves them.","source":"unit-01","difficulty":"core","unit":"Unit 01","originalSource":"quiz","type":"evidence"},{"id":"u01-q-q14","domain":"Uncertainty","prompt":"Which statement correctly distinguishes random variation from systematic bias?","options":["Repeating measurements always eliminates both.","Random variation can cause unpredictable trial-to-trial differences, while systematic bias can shift measurements consistently and may persist across repetitions.","Systematic bias is simply any unusual data point.","Random variation means the experiment was conducted incorrectly."],"answer":1,"explanation":"Replication can help characterize some random variation, while systematic bias often requires calibration, reference checks, sampling changes, or redesign.","source":"unit-01","difficulty":"core","unit":"Unit 01","originalSource":"quiz","type":"evidence"},{"id":"u01-q-q15","domain":"Safety and design","prompt":"A planned investigation has a hazard that cannot be reasonably controlled with the available equipment and supervision. What should happen before data collection?","options":["Continue because completing the dataset is more important.","Hide the hazard from the record.","Revise, replace, or postpone the method until the risk can be acceptably controlled.","Collect fewer trials so exposure is shorter."],"answer":2,"explanation":"Scientific work does not justify an uncontrolled hazard. The design must be changed or postponed before beginning.","source":"unit-01","difficulty":"core","unit":"Unit 01","originalSource":"quiz","type":"concept"},{"id":"u01-a-a01","domain":"Questions & hypotheses","prompt":"Which question identifies a deliberately changed variable, a measurable response, and conditions that can be compared?","options":["How does salt concentration affect the melting time of equal-mass ice cubes under the same room conditions?","Which ice cube looks nicest?","Should salt be used?","Are plants good?"],"answer":0,"explanation":"A strong investigable question identifies measurable variables and a defined comparison rather than asking for preference or judgment.","source":"unit-01","difficulty":"transfer","unit":"Unit 01","originalSource":"assessment","type":"concept"},{"id":"u01-a-a02","domain":"Questions & hypotheses","prompt":"Which prediction is testable, directional, and appropriately scoped?","options":["Light is important.","If daily light duration increases, then mean seedling height after 14 days will increase within the tested light-duration range, assuming the other stated growth conditions are controlled.","Plants are interesting.","The result will prove the hypothesis."],"answer":1,"explanation":"The prediction gives a measurable direction and limits the claim to the tested conditions.","source":"unit-01","difficulty":"transfer","unit":"Unit 01","originalSource":"assessment","type":"concept"},{"id":"u01-a-a03","domain":"Questions & hypotheses","prompt":"A preregistered prediction is not supported by the results. What is the strongest scientific response?","options":["Rewrite the prediction and pretend the new version came first.","Delete results that disagree.","Report that the results did not support the prediction, evaluate the method and evidence, and revise the explanation if warranted.","Declare the investigation a failure with no useful information."],"answer":2,"explanation":"Unsupported predictions should be reported honestly. Scientific value comes from evaluating evidence, not forcing results to match expectations.","source":"unit-01","difficulty":"transfer","unit":"Unit 01","originalSource":"assessment","type":"concept"},{"id":"u01-a-a04","domain":"Variables & controls","prompt":"A student investigates how pendulum length affects period. Which is the independent variable?","options":["Period","Number of timing trials","Graph scale","Pendulum length"],"answer":3,"explanation":"Pendulum length is the factor deliberately changed.","source":"unit-01","difficulty":"transfer","unit":"Unit 01","originalSource":"assessment","type":"concept"},{"id":"u01-a-a05","domain":"Variables & controls","prompt":"In the pendulum investigation, why should release angle be controlled?","options":["Because changing it systematically with length could create an alternative explanation for period differences.","Because every controlled variable must equal zero.","Because it determines the graph title.","Because it is the measured outcome."],"answer":0,"explanation":"A control limits plausible alternative explanations by preventing another factor from changing systematically with the independent variable.","source":"unit-01","difficulty":"transfer","unit":"Unit 01","originalSource":"assessment","type":"concept"},{"id":"u01-a-a06","domain":"Variables & controls","prompt":"Which statement best describes a confounder?","options":["Any variable written in the notebook.","A variable related to the explanatory condition and the outcome that can create or distort an apparent relationship.","Only an obviously incorrect measurement.","The dependent variable in every experiment."],"answer":1,"explanation":"A confounder can provide an alternative explanation because it varies with both the explanatory condition and the response.","source":"unit-01","difficulty":"transfer","unit":"Unit 01","originalSource":"assessment","type":"concept"},{"id":"u01-a-a07","domain":"Measurement","prompt":"Which tool is most appropriate for timing a paper-helicopter fall lasting about 1.5 seconds?","options":["A meter stick only","A thermometer","A stopwatch/timer with sub-second resolution","A kilogram scale"],"answer":2,"explanation":"The instrument must measure the correct quantity and have resolution appropriate to the event duration.","source":"unit-01","difficulty":"transfer","unit":"Unit 01","originalSource":"assessment","type":"quantitative"},{"id":"u01-a-a08","domain":"Measurement","prompt":"Which statement correctly distinguishes accuracy from precision?","options":["Accuracy and precision always mean the same thing.","Precision proves there is no systematic bias.","Accuracy describes graph scale.","Accuracy is closeness to an appropriate reference; precision is closeness among repeated measurements."],"answer":3,"explanation":"Repeated measurements can be precise yet systematically shifted from an appropriate reference.","source":"unit-01","difficulty":"transfer","unit":"Unit 01","originalSource":"assessment","type":"quantitative"},{"id":"u01-a-a09","domain":"Measurement","prompt":"A digital balance displays mass to the nearest 0.1 g. Which reporting choice is most defensible?","options":["18.4 g when that is the displayed measurement","18.43726 g because a calculator can show extra digits","18 g exactly with no stated limitation","18.4 mL"],"answer":0,"explanation":"Reported digits should be supported by the instrument and method; calculator digits do not create measurement information.","source":"unit-01","difficulty":"transfer","unit":"Unit 01","originalSource":"assessment","type":"quantitative"},{"id":"u01-a-a10","domain":"Measurement","prompt":"Five repeated measurements are tightly clustered, but a calibration check shows the instrument reads 0.5 units high. What does this show?","options":["The range must be zero.","High precision can coexist with systematic bias.","The measurements must be accurate because they agree.","Repeated trials automatically removed the bias."],"answer":1,"explanation":"Consistency among repeated measurements does not guarantee accuracy when a systematic offset is present.","source":"unit-01","difficulty":"transfer","unit":"Unit 01","originalSource":"assessment","type":"quantitative"},{"id":"u01-a-a11","domain":"Data integrity","prompt":"Which procedure best protects the integrity of repeated-trial data?","options":["Delete unusual values before recording them.","Replace raw observations with the mean.","Record every planned trial and document any protocol deviation before deciding how it affects analysis.","Repeat only results that disagree with the prediction."],"answer":2,"explanation":"Raw observations and deviations should remain auditable; analysis decisions should not be based on whether a result is convenient.","source":"unit-01","difficulty":"transfer","unit":"Unit 01","originalSource":"assessment","type":"evidence"},{"id":"u01-a-a12","domain":"Data integrity","prompt":"A trial is far from the others but no procedural failure was observed. What should the investigator do first?","options":["Change it to the nearest expected value.","Use only that trial.","Delete it as an error.","Preserve and flag it, investigate possible explanations, and evaluate its influence transparently."],"answer":3,"explanation":"An unusual observation is a question for investigation, not an automatic deletion rule.","source":"unit-01","difficulty":"transfer","unit":"Unit 01","originalSource":"assessment","type":"evidence"},{"id":"u01-a-a13","domain":"Tables & graphs","prompt":"Which table heading is scientifically complete?","options":["Fall time (s)","Results","Numbers","Time"],"answer":0,"explanation":"A complete quantitative heading identifies both the variable and its unit.","source":"unit-01","difficulty":"transfer","unit":"Unit 01","originalSource":"assessment","type":"concept"},{"id":"u01-a-a14","domain":"Tables & graphs","prompt":"Paper type is categorical and water absorbed is numerical. Which graph is generally appropriate for comparing mean water absorbed among paper types?","options":["A pie chart of unrelated totals","A bar chart with paper type on the x-axis and mean water absorbed (g) on the y-axis","A line graph implying paper types form a continuous sequence","An unlabeled sketch"],"answer":1,"explanation":"A bar chart can compare a numerical summary across discrete categories; raw trial data should remain available behind the summary.","source":"unit-01","difficulty":"transfer","unit":"Unit 01","originalSource":"assessment","type":"concept"},{"id":"u01-a-a15","domain":"Tables & graphs","prompt":"Which graph is generally appropriate for examining the association between estimated shade percentage and surface temperature?","options":["Decorative icon chart","Unscaled diagram","Scatter plot","Pie chart"],"answer":2,"explanation":"A scatter plot displays paired values for two numerical variables.","source":"unit-01","difficulty":"transfer","unit":"Unit 01","originalSource":"assessment","type":"concept"},{"id":"u01-a-a16","domain":"Tables & graphs","prompt":"Two graphs show the same data but use different y-axis ranges. What is the most defensible conclusion?","options":["Every numerical axis must always begin at zero.","Axis choices never affect interpretation.","The steeper-looking graph is automatically more accurate.","Scale can change visual impression without changing the data, so readers should inspect ranges, intervals, labels, and context."],"answer":3,"explanation":"Scale is part of data communication. A truncated axis can be useful, but it can also visually magnify small differences if context is ignored.","source":"unit-01","difficulty":"transfer","unit":"Unit 01","originalSource":"assessment","type":"concept"},{"id":"u01-a-a17","domain":"Data analysis","prompt":"The fall times 1.4 s, 1.5 s, 1.5 s, 1.6 s, and 1.5 s have a mean of:","options":["1.5 s","1.6 s","7.5 s","1.0 s"],"answer":0,"explanation":"The total is 7.5 s; 7.5 ÷ 5 = 1.5 s.","source":"unit-01","difficulty":"transfer","unit":"Unit 01","originalSource":"assessment","type":"concept"},{"id":"u01-a-a18","domain":"Data analysis","prompt":"For the same values, what does the 0.2 s range describe?","options":["The number of trials.","The observed spread from the minimum to maximum trial.","The accuracy of the timer.","The causal effect of the independent variable."],"answer":1,"explanation":"Range equals maximum minus minimum and summarizes observed spread; it does not establish accuracy or causation.","source":"unit-01","difficulty":"transfer","unit":"Unit 01","originalSource":"assessment","type":"concept"},{"id":"u01-a-a19","domain":"Inference","prompt":"A pattern appears in one limited study. Which conclusion is best calibrated to the evidence?","options":["There are no remaining alternative explanations.","One variable definitely caused the other regardless of design.","The pattern was observed under these study conditions and should be evaluated with limitations and additional evidence.","The pattern is universally true."],"answer":2,"explanation":"Scientific claims should match the scope, design, uncertainty, and limitations of the evidence.","source":"unit-01","difficulty":"transfer","unit":"Unit 01","originalSource":"assessment","type":"evidence"},{"id":"u01-a-a20","domain":"Inference","prompt":"A study observes that students who sleep longer tend to have higher test scores but does not assign sleep schedules. Which claim is justified directly by that design?","options":["Higher scores caused longer sleep.","No third variable could matter.","Longer sleep caused every higher score.","Sleep duration and test score were associated in the observed sample."],"answer":3,"explanation":"The observational design supports an association; confounding and direction-of-causation alternatives remain possible.","source":"unit-01","difficulty":"transfer","unit":"Unit 01","originalSource":"assessment","type":"concept"},{"id":"u01-a-a21","domain":"Causal reasoning","prompt":"Which design change most strengthens causal inference when it is safe and ethical?","options":["Deliberately manipulate one factor while controlling or randomizing plausible alternatives where feasible.","Remove the comparison condition.","Select only observations that fit the prediction.","Change several factors together."],"answer":0,"explanation":"Controlled manipulation and design features that reduce alternative explanations strengthen causal inference.","source":"unit-01","difficulty":"transfer","unit":"Unit 01","originalSource":"assessment","type":"evidence"},{"id":"u01-a-a22","domain":"CER","prompt":"Which statement is reasoning rather than merely evidence or claim?","options":["Longer rotors had longer mean fall times in this test.","Because rotor geometry can affect interaction with air, and rotor length was deliberately varied while stated conditions were controlled, the measured pattern supports an effect of rotor length under these tested conditions, subject to the listed limitations.","Five trials were recorded.","The mean fall time was 1.8 s."],"answer":1,"explanation":"Reasoning connects the evidence to the claim using scientific ideas and the design while respecting limitations.","source":"unit-01","difficulty":"transfer","unit":"Unit 01","originalSource":"assessment","type":"evidence"},{"id":"u01-a-a23","domain":"Sources","prompt":"A dramatic news headline makes a scientific claim. Which action provides the strongest source check?","options":["Reject it automatically because it is news.","Count how many times it was reposted.","Trace the claim toward the original study, dataset, or agency report and compare its method, scope, and limitations with the headline.","Trust it because it names a scientist."],"answer":2,"explanation":"Evidence proximity and method transparency allow the public claim to be compared with the original evidence.","source":"unit-01","difficulty":"transfer","unit":"Unit 01","originalSource":"assessment","type":"evidence"},{"id":"u01-a-a24","domain":"Safety & design","prompt":"During planning, an investigator discovers a hazard that cannot be reasonably controlled with available equipment or supervision. What should happen?","options":["Use fewer trials and proceed anyway.","Continue because data are important.","Remove the hazard from the written record.","Revise, replace, or postpone the method before collecting data."],"answer":3,"explanation":"Scientific value does not justify an uncontrolled hazard; the method must be made acceptably safe before data collection.","source":"unit-01","difficulty":"transfer","unit":"Unit 01","originalSource":"assessment","type":"concept"},{"id":"u02-q-q02","domain":"Cell theory","prompt":"Which observation most directly supports the conclusion that a specimen is cellular?","options":["It is green.","Repeated microscope views show membrane-bounded units with internal contents.","It moves when pushed.","It has a measurable mass."],"answer":1,"explanation":"Repeated observation of membrane-bounded units is direct evidence of cellular organization.","source":"unit-02","difficulty":"core","unit":"Unit 02","originalSource":"quiz","type":"concept"},{"id":"u02-q-q03","domain":"Cell types","prompt":"Which structure is present in both prokaryotic and eukaryotic cells?","options":["Mitochondrion","Golgi apparatus","Ribosome","Membrane-bound nucleus"],"answer":2,"explanation":"All cells use ribosomes to build proteins.","source":"unit-02","difficulty":"core","unit":"Unit 02","originalSource":"quiz","type":"model"},{"id":"u02-q-q04","domain":"Cell types","prompt":"Which feature distinguishes a eukaryotic cell from a prokaryotic cell?","options":["Ribosomes","A plasma membrane","Cytoplasm","DNA enclosed within a membrane-bound nucleus"],"answer":3,"explanation":"Eukaryotic DNA is enclosed within a membrane-bound nucleus.","source":"unit-02","difficulty":"core","unit":"Unit 02","originalSource":"quiz","type":"concept"},{"id":"u02-q-q05","domain":"Organelles","prompt":"Which organelle is the main site of aerobic cellular respiration in eukaryotic cells?","options":["Mitochondrion","Ribosome","Cell wall","Vacuole"],"answer":0,"explanation":"Most stages of aerobic cellular respiration occur in mitochondria.","source":"unit-02","difficulty":"core","unit":"Unit 02","originalSource":"quiz","type":"concept"},{"id":"u02-q-q06","domain":"Organelles","prompt":"What is the primary role of ribosomes?","options":["Production of cellulose cell walls","Protein synthesis","Storage of hereditary information","Control of water movement by osmosis"],"answer":1,"explanation":"Ribosomes assemble amino acids into proteins.","source":"unit-02","difficulty":"core","unit":"Unit 02","originalSource":"quiz","type":"concept"},{"id":"u02-q-q07","domain":"Plant cells","prompt":"Which statement about plant cells is correct?","options":["All plant cells contain chloroplasts.","Plant cells do not contain mitochondria.","Photosynthetic plant cells commonly contain chloroplasts and mitochondria.","Plant cells lack a plasma membrane."],"answer":2,"explanation":"Photosynthetic plant cells commonly contain both chloroplasts and mitochondria.","source":"unit-02","difficulty":"core","unit":"Unit 02","originalSource":"quiz","type":"concept"},{"id":"u02-q-q08","domain":"Microscopy","prompt":"An image is 30 mm long and the specimen is 0.06 mm long. What is the magnification?","options":["×5000","×5","×50","×500"],"answer":3,"explanation":"30 ÷ 0.06 = 500.","source":"unit-02","difficulty":"core","unit":"Unit 02","originalSource":"quiz","type":"quantitative"},{"id":"u02-q-q09","domain":"Microscopy","prompt":"Which conversion is correct?","options":["1 mm = 1000 µm","1 µm = 1000 mm","1 mm = 10 µm","1 mm = 100 µm"],"answer":0,"explanation":"One millimeter equals one thousand micrometers.","source":"unit-02","difficulty":"core","unit":"Unit 02","originalSource":"quiz","type":"concept"},{"id":"u02-q-q10","domain":"Membranes","prompt":"What does selectively permeable mean?","options":["No substances can cross the membrane.","The membrane allows some substances to cross more readily than others.","Every substance crosses at the same rate.","Only water can ever cross."],"answer":1,"explanation":"Passage depends on properties such as size, charge, concentration, and transport proteins.","source":"unit-02","difficulty":"core","unit":"Unit 02","originalSource":"quiz","type":"concept"},{"id":"u02-q-q11","domain":"Diffusion","prompt":"Diffusion is best described as:","options":["Movement against a concentration gradient using cellular energy","The production of glucose using light","Net movement of particles from higher concentration to lower concentration due to random motion","Movement of water only through a membrane"],"answer":2,"explanation":"Diffusion is net movement down a concentration gradient arising from random particle motion.","source":"unit-02","difficulty":"core","unit":"Unit 02","originalSource":"quiz","type":"concept"},{"id":"u02-q-q12","domain":"Osmosis","prompt":"Osmosis specifically refers to the net movement of:","options":["Proteins from low concentration to high concentration","Oxygen using ATP","Any solute through any barrier","Water through a selectively permeable membrane"],"answer":3,"explanation":"Osmosis is net water movement through a selectively permeable membrane.","source":"unit-02","difficulty":"core","unit":"Unit 02","originalSource":"quiz","type":"concept"},{"id":"u02-q-q13","domain":"Transport","prompt":"Which process can move a substance against its concentration gradient?","options":["Active transport","Random mixing only","Simple diffusion","Osmosis"],"answer":0,"explanation":"Active transport uses cellular energy and transport proteins.","source":"unit-02","difficulty":"core","unit":"Unit 02","originalSource":"quiz","type":"concept"},{"id":"u02-q-q14","domain":"Cell size","prompt":"As a cube-shaped cell becomes larger, what generally happens to its surface-area-to-volume ratio?","options":["It increases","It decreases","It remains constant","It becomes zero immediately"],"answer":1,"explanation":"Volume increases faster than surface area.","source":"unit-02","difficulty":"core","unit":"Unit 02","originalSource":"quiz","type":"concept"},{"id":"u02-q-q15","domain":"Cell size","prompt":"Why is a higher surface-area-to-volume ratio often advantageous for a cell?","options":["It prevents all diffusion.","It guarantees the cell will be multicellular.","It increases exchange surface relative to the material that must be supplied.","It removes the need for a membrane."],"answer":2,"explanation":"More membrane surface relative to volume can support faster exchange per unit volume.","source":"unit-02","difficulty":"core","unit":"Unit 02","originalSource":"quiz","type":"concept"},{"id":"u02-q-q16","domain":"Specialization","prompt":"Which adaptation most directly helps a red blood cell carry oxygen?","options":["A cellulose wall","Chloroplasts","A large central vacuole","A biconcave shape and abundant hemoglobin"],"answer":3,"explanation":"The biconcave shape increases exchange area, and hemoglobin binds oxygen.","source":"unit-02","difficulty":"core","unit":"Unit 02","originalSource":"quiz","type":"concept"},{"id":"u02-q-q17","domain":"Organization","prompt":"Which sequence shows increasing biological organization in a multicellular organism?","options":["Cell → tissue → organ → organ system","Tissue → cell → organ system → organ","Cell → organ system → tissue → organ","Organ → tissue → cell → system"],"answer":0,"explanation":"Specialized cells form tissues; tissues form organs; organs cooperate in systems.","source":"unit-02","difficulty":"core","unit":"Unit 02","originalSource":"quiz","type":"model"},{"id":"u02-q-q18","domain":"Energy","prompt":"Which statement correctly compares photosynthesis and cellular respiration?","options":["Only animals perform cellular respiration.","Photosynthesis stores energy in organic molecules; cellular respiration releases usable chemical energy from organic molecules.","Both processes occur only in chloroplasts.","Photosynthesis consumes oxygen and releases glucose."],"answer":1,"explanation":"Photosynthesis stores light energy; respiration transfers energy from organic molecules to usable cellular forms.","source":"unit-02","difficulty":"core","unit":"Unit 02","originalSource":"quiz","type":"concept"},{"id":"u02-q-q19","domain":"Models","prompt":"Which is a limitation of a typical textbook cell diagram?","options":["It proves every cell has the same shape.","It is always a direct photograph.","It may show structures at unrealistic relative sizes and fixed positions.","It contains no information at all."],"answer":2,"explanation":"Diagrams simplify and reorganize structures for clarity.","source":"unit-02","difficulty":"core","unit":"Unit 02","originalSource":"quiz","type":"model"},{"id":"u02-q-q20","domain":"Evidence","prompt":"A microscope image shows a cell wall and chloroplasts. Which conclusion is best supported?","options":["The cell must be a bacterium.","The cell cannot perform respiration.","Every cell in the organism has chloroplasts.","The cell is a photosynthetic eukaryotic cell."],"answer":3,"explanation":"A cell wall plus chloroplasts supports classification as a photosynthetic eukaryotic cell.","source":"unit-02","difficulty":"core","unit":"Unit 02","originalSource":"quiz","type":"evidence"},{"id":"u02-a-a01","domain":"Cell theory","prompt":"Which statement is NOT part of modern cell theory?","options":["Every cell contains a membrane-bound nucleus.","Cells are the basic unit of life.","Living organisms are made of one or more cells.","New cells arise from pre-existing cells."],"answer":0,"explanation":"Prokaryotic cells do not contain a membrane-bound nucleus.","source":"unit-02","difficulty":"transfer","unit":"Unit 02","originalSource":"assessment","type":"concept"},{"id":"u02-a-a02","domain":"Cell theory","prompt":"Why did improved microscopes strengthen cell theory?","options":["They proved viruses are cells.","They allowed repeated observation of cells and cell division in many organisms.","They made living things larger.","They removed the need for evidence."],"answer":1,"explanation":"Improved microscopes provided repeatable observations of cellular structure and reproduction.","source":"unit-02","difficulty":"transfer","unit":"Unit 02","originalSource":"assessment","type":"concept"},{"id":"u02-a-a03","domain":"Cell theory","prompt":"Which entity is acellular rather than a complete cell?","options":["Bacterium","Yeast cell","Virus particle","Amoeba"],"answer":2,"explanation":"Viruses are acellular particles that depend on host cells for replication.","source":"unit-02","difficulty":"transfer","unit":"Unit 02","originalSource":"assessment","type":"concept"},{"id":"u02-a-a04","domain":"Cell types","prompt":"Which feature is found in a typical bacterial cell?","options":["A membrane-bound nucleus","Mitochondria","Chloroplasts","Circular DNA in a nucleoid region"],"answer":3,"explanation":"Typical bacteria have DNA in a nucleoid region.","source":"unit-02","difficulty":"transfer","unit":"Unit 02","originalSource":"assessment","type":"concept"},{"id":"u02-a-a05","domain":"Cell types","prompt":"Which pair is present in all known cells?","options":["Plasma membrane and ribosomes","Nucleus and mitochondria","Cell wall and chloroplasts","Golgi apparatus and lysosomes"],"answer":0,"explanation":"All cells have a plasma membrane and ribosomes.","source":"unit-02","difficulty":"transfer","unit":"Unit 02","originalSource":"assessment","type":"concept"},{"id":"u02-a-a06","domain":"Cell types","prompt":"Which statement avoids an inaccurate hierarchy between prokaryotes and eukaryotes?","options":["Prokaryotes are unfinished eukaryotic cells.","Prokaryotes and eukaryotes have different cellular organizations adapted to their ways of life.","Eukaryotes are always more successful.","Prokaryotes have no internal organization."],"answer":1,"explanation":"Both groups are highly evolved and differ in organization.","source":"unit-02","difficulty":"transfer","unit":"Unit 02","originalSource":"assessment","type":"concept"},{"id":"u02-a-a07","domain":"Organelles","prompt":"Which organelle modifies, sorts, and packages many proteins in eukaryotic cells?","options":["Nucleoid","Chloroplast","Golgi apparatus","Cell wall"],"answer":2,"explanation":"The Golgi apparatus modifies, sorts, and packages many proteins and lipids.","source":"unit-02","difficulty":"transfer","unit":"Unit 02","originalSource":"assessment","type":"concept"},{"id":"u02-a-a08","domain":"Organelles","prompt":"Which structure contains most of a eukaryotic cell's DNA?","options":["Ribosome","Cell wall","Cytosol","Nucleus"],"answer":3,"explanation":"Most eukaryotic DNA is enclosed in the nucleus.","source":"unit-02","difficulty":"transfer","unit":"Unit 02","originalSource":"assessment","type":"model"},{"id":"u02-a-a09","domain":"Organelles","prompt":"Which structure provides rigid support outside the plasma membrane of plant cells?","options":["Cellulose cell wall","Mitochondrion","Nucleus","Ribosome"],"answer":0,"explanation":"The cellulose cell wall supports and protects plant cells.","source":"unit-02","difficulty":"transfer","unit":"Unit 02","originalSource":"assessment","type":"model"},{"id":"u02-a-a10","domain":"Organelles","prompt":"What is a central role of a large plant-cell vacuole?","options":["Carrying out all cellular respiration","Maintaining internal water storage and turgor pressure","Producing ribosomes","Enclosing the cell's chromosomes"],"answer":1,"explanation":"The central vacuole stores water and solutes and helps maintain turgor.","source":"unit-02","difficulty":"transfer","unit":"Unit 02","originalSource":"assessment","type":"concept"},{"id":"u02-a-a11","domain":"Microscopy","prompt":"A 24 mm image was produced at ×400 magnification. What is the actual specimen length?","options":["6 mm","9600 mm","0.06 mm","0.6 mm"],"answer":2,"explanation":"24 ÷ 400 = 0.06 mm.","source":"unit-02","difficulty":"transfer","unit":"Unit 02","originalSource":"assessment","type":"concept"},{"id":"u02-a-a12","domain":"Microscopy","prompt":"What is 0.06 mm expressed in micrometers?","options":["6000 µm","0.06 µm","6 µm","60 µm"],"answer":3,"explanation":"0.06 mm × 1000 = 60 µm.","source":"unit-02","difficulty":"transfer","unit":"Unit 02","originalSource":"assessment","type":"concept"},{"id":"u02-a-a13","domain":"Microscopy","prompt":"A ×10 eyepiece and ×40 objective produce what total magnification?","options":["×400","×4000","×4","×50"],"answer":0,"explanation":"10 × 40 = 400.","source":"unit-02","difficulty":"transfer","unit":"Unit 02","originalSource":"assessment","type":"concept"},{"id":"u02-a-a14","domain":"Microscopy","prompt":"Which observation method gives the strongest evidence about a cell's three-dimensional internal structure?","options":["A single simplified diagram","Multiple images or sections from different depths and orientations","A title without an image","One color label"],"answer":1,"explanation":"Multiple sections or orientations provide stronger three-dimensional evidence.","source":"unit-02","difficulty":"transfer","unit":"Unit 02","originalSource":"assessment","type":"evidence"},{"id":"u02-a-a15","domain":"Membranes","prompt":"Which factor can directly influence whether an ion crosses a cell membrane?","options":["The diagram's background color","Whether the organism is visible without a microscope","Availability and state of a suitable membrane transport protein","The cell's name"],"answer":2,"explanation":"Charged ions generally require specific channels or carriers.","source":"unit-02","difficulty":"transfer","unit":"Unit 02","originalSource":"assessment","type":"concept"},{"id":"u02-a-a16","domain":"Diffusion","prompt":"At diffusion equilibrium, particles:","options":["All move in one direction.","Require ATP for every movement.","Stop moving completely.","Continue random motion, but there is no net concentration change."],"answer":3,"explanation":"Particles continue random motion while net movement is balanced.","source":"unit-02","difficulty":"transfer","unit":"Unit 02","originalSource":"assessment","type":"model"},{"id":"u02-a-a17","domain":"Diffusion","prompt":"Which change would generally increase the diffusion rate of dye in water?","options":["Increasing temperature within the safe tested range","Eliminating the concentration gradient","Increasing diffusion distance","Turning the water into a solid"],"answer":0,"explanation":"Higher temperature generally increases particle motion.","source":"unit-02","difficulty":"transfer","unit":"Unit 02","originalSource":"assessment","type":"concept"},{"id":"u02-a-a18","domain":"Osmosis","prompt":"A plant cell is placed in a solution more dilute than its cell contents. What is the expected net water movement?","options":["Water changes into solute","Into the cell","Out of the cell","No water molecules move"],"answer":1,"explanation":"Water tends to move into the more concentrated cell contents.","source":"unit-02","difficulty":"transfer","unit":"Unit 02","originalSource":"assessment","type":"concept"},{"id":"u02-a-a19","domain":"Osmosis","prompt":"A potato sample changes from 5.0 g to 4.5 g. What is the percent mass change?","options":["−0.5%","+0.5%","−10%","+10%"],"answer":2,"explanation":"(4.5 − 5.0) ÷ 5.0 × 100 = −10%.","source":"unit-02","difficulty":"transfer","unit":"Unit 02","originalSource":"assessment","type":"quantitative"},{"id":"u02-a-a20","domain":"Transport","prompt":"Which condition is required for active transport?","options":["Movement only from high to low concentration","No membrane","A dead cell with no metabolism","A cellular energy supply and suitable transport proteins"],"answer":3,"explanation":"Active transport depends on energy and specific membrane proteins.","source":"unit-02","difficulty":"transfer","unit":"Unit 02","originalSource":"assessment","type":"concept"},{"id":"u02-a-a21","domain":"Transport","prompt":"Which example is best explained by active transport?","options":["Mineral ions accumulated by root cells against a concentration gradient","Perfume spreading across a room","Water entering a cell by osmosis","Food coloring dispersing in water"],"answer":0,"explanation":"Root cells can accumulate mineral ions against their gradient.","source":"unit-02","difficulty":"transfer","unit":"Unit 02","originalSource":"assessment","type":"concept"},{"id":"u02-a-a22","domain":"Cell size","prompt":"What is the surface-area-to-volume ratio of a cube with side length 2 cm?","options":["24:1","3:1","6:1","8:1"],"answer":1,"explanation":"Surface area 24 and volume 8 give 3:1.","source":"unit-02","difficulty":"transfer","unit":"Unit 02","originalSource":"assessment","type":"concept"},{"id":"u02-a-a23","domain":"Cell size","prompt":"Which adaptation increases exchange surface without greatly increasing cell volume?","options":["Making the cell a solid block","Eliminating concentration gradients","Folds or projections in the membrane","Removing the membrane"],"answer":2,"explanation":"Folds and projections increase membrane surface area.","source":"unit-02","difficulty":"transfer","unit":"Unit 02","originalSource":"assessment","type":"concept"},{"id":"u02-a-a24","domain":"Specialization","prompt":"Which structure-function relationship is correct?","options":["Neuron — cellulose wall speeds electrical signaling","Sperm cell — chloroplasts provide propulsion","Palisade cell — no chloroplasts","Root hair cell — long projection increases absorption surface"],"answer":3,"explanation":"A root hair cell's projection increases absorption surface.","source":"unit-02","difficulty":"transfer","unit":"Unit 02","originalSource":"assessment","type":"model"},{"id":"u02-a-a25","domain":"Specialization","prompt":"Why can specialized cells in a multicellular organism depend on one another?","options":["They divide labor and exchange materials through tissues and systems.","Each performs every possible function independently.","Specialization removes the need for transport.","All specialized cells have identical structures."],"answer":0,"explanation":"Specialization divides functions and creates interdependence.","source":"unit-02","difficulty":"transfer","unit":"Unit 02","originalSource":"assessment","type":"concept"},{"id":"u02-a-a26","domain":"Organization","prompt":"Which example is an organ?","options":["Circulatory system","Heart","Cardiac muscle tissue","Cardiac muscle cell"],"answer":1,"explanation":"The heart is an organ composed of multiple tissues.","source":"unit-02","difficulty":"transfer","unit":"Unit 02","originalSource":"assessment","type":"model"},{"id":"u02-a-a27","domain":"Energy","prompt":"Which substances are reactants in photosynthesis?","options":["Protein and ATP","Oxygen and water only","Carbon dioxide and water","Glucose and oxygen"],"answer":2,"explanation":"Photosynthesis uses carbon dioxide and water with light energy.","source":"unit-02","difficulty":"transfer","unit":"Unit 02","originalSource":"assessment","type":"concept"},{"id":"u02-a-a28","domain":"Energy","prompt":"Which statement about plant cellular respiration is correct?","options":["Plant cells perform respiration only at night.","Only chloroplasts perform respiration.","Respiration creates energy from nothing.","Plant cells perform cellular respiration as well as photosynthesis."],"answer":3,"explanation":"Plant cells respire continuously; photosynthetic cells also photosynthesize in suitable light.","source":"unit-02","difficulty":"transfer","unit":"Unit 02","originalSource":"assessment","type":"concept"},{"id":"u02-a-a29","domain":"Models","prompt":"Why should a model include a stated limitation?","options":["Every model emphasizes some features and omits or simplifies others.","Models contain no evidence.","A limitation makes every conclusion false.","Scientific models never change."],"answer":0,"explanation":"Models are selective representations.","source":"unit-02","difficulty":"transfer","unit":"Unit 02","originalSource":"assessment","type":"model"},{"id":"u02-a-a30","domain":"Evidence","prompt":"A student claims every plant cell contains chloroplasts after viewing one leaf cell. What is the best evaluation?","options":["The claim shows chloroplasts occur in animal cells.","The claim is too broad because one leaf cell does not represent all plant cell types.","The claim is proven for every plant cell.","The claim proves roots photosynthesize."],"answer":1,"explanation":"One leaf cell cannot justify a universal claim about every plant cell type.","source":"unit-02","difficulty":"transfer","unit":"Unit 02","originalSource":"assessment","type":"evidence"},{"id":"u03-q-x02","domain":"Systems and homeostasis","prompt":"In negative feedback, the response generally:","options":["Stops communication","Opposes the initial change","Amplifies change without limit","Removes the receptor"],"answer":1,"explanation":"Negative feedback counteracts deviation.","source":"unit-03","difficulty":"core","unit":"Unit 03","originalSource":"quiz","type":"model"},{"id":"u03-q-x04","domain":"Systems and homeostasis","prompt":"Which is commonly modeled as positive feedback?","options":["Sweating","Insulin after a meal","Water conservation","Blood clotting at a damaged vessel"],"answer":3,"explanation":"Clotting amplifies locally until the break is sealed.","source":"unit-03","difficulty":"core","unit":"Unit 03","originalSource":"quiz","type":"model"},{"id":"u03-q-x05","domain":"Systems and homeostasis","prompt":"Right ventricle to left atrium route:","options":["Pulmonary artery → lung capillaries → pulmonary veins","Aorta → body → vena cava","Pulmonary vein → body → aorta","Vena cava → kidney → pulmonary artery"],"answer":0,"explanation":"This is pulmonary circulation.","source":"unit-03","difficulty":"core","unit":"Unit 03","originalSource":"quiz","type":"model"},{"id":"u03-q-x06","domain":"Systems and homeostasis","prompt":"Which statement is correct?","options":["Only veins have walls","Arteries carry blood away; veins carry blood toward the heart","Arteries always carry oxygen-rich blood","Veins always carry oxygen-poor blood"],"answer":1,"explanation":"Direction defines the vessel type.","source":"unit-03","difficulty":"core","unit":"Unit 03","originalSource":"quiz","type":"model"},{"id":"u03-q-x07","domain":"Systems and homeostasis","prompt":"Which alveolar feature supports rapid exchange?","options":["No blood supply","Cellulose walls","Large surface area and thin surfaces","Thick dry walls"],"answer":2,"explanation":"Large area and short distance support diffusion.","source":"unit-03","difficulty":"core","unit":"Unit 03","originalSource":"quiz","type":"model"},{"id":"u03-q-x08","domain":"Systems and homeostasis","prompt":"Breathing and cellular respiration differ because:","options":["Breathing produces glucose","Respiration occurs only in lungs","They are identical","Breathing moves air; respiration transfers chemical energy in cells"],"answer":3,"explanation":"They are distinct processes.","source":"unit-03","difficulty":"core","unit":"Unit 03","originalSource":"quiz","type":"model"},{"id":"u03-q-x09","domain":"Systems and homeostasis","prompt":"Why does heart rate often rise during activity?","options":["To increase transport and heat/waste removal","To stop blood flow","To thicken alveoli","To eliminate all temperature variation"],"answer":0,"explanation":"Transport demand increases.","source":"unit-03","difficulty":"core","unit":"Unit 03","originalSource":"quiz","type":"model"},{"id":"u03-q-x10","domain":"Systems and homeostasis","prompt":"Chemical digestion mainly:","options":["Converts nutrients to heat before absorption","Breaks large insoluble molecules into small soluble molecules","Moves only undigested food","Produces oxygen"],"answer":1,"explanation":"Small soluble molecules can be absorbed.","source":"unit-03","difficulty":"core","unit":"Unit 03","originalSource":"quiz","type":"model"},{"id":"u03-q-x11","domain":"Systems and homeostasis","prompt":"Which increases small-intestine absorption area?","options":["One large chamber","Cartilage rings","Villi and microvilli","Keratin"],"answer":2,"explanation":"Villi and microvilli increase surface area.","source":"unit-03","difficulty":"core","unit":"Unit 03","originalSource":"quiz","type":"model"},{"id":"u03-q-x12","domain":"Systems and homeostasis","prompt":"Kidneys mainly excrete:","options":["Undigested food","Oxygen and glucose","Antibodies and red cells","Urea, excess water, and excess ions"],"answer":3,"explanation":"These are major urine components.","source":"unit-03","difficulty":"core","unit":"Unit 03","originalSource":"quiz","type":"model"},{"id":"u03-q-x13","domain":"Systems and homeostasis","prompt":"During dehydration, increased ADH causes:","options":["More water reabsorption and lower urine volume","Excretion of all water","Permanent stop of filtration","Glucose release into urine"],"answer":0,"explanation":"ADH helps conserve water.","source":"unit-03","difficulty":"core","unit":"Unit 03","originalSource":"quiz","type":"model"},{"id":"u03-q-x14","domain":"Systems and homeostasis","prompt":"Which helps increase heat loss?","options":["Stopping circulation","Sweating and increased skin blood flow","Shivering and reduced skin flow","Reducing evaporation"],"answer":1,"explanation":"These support cooling.","source":"unit-03","difficulty":"core","unit":"Unit 03","originalSource":"quiz","type":"model"},{"id":"u03-q-x15","domain":"Systems and homeostasis","prompt":"After blood glucose rises, insulin promotes:","options":["Shutdown of respiration","Conversion of all proteins to glucose","Uptake and storage","Release of stored glucose"],"answer":2,"explanation":"Insulin lowers elevated glucose.","source":"unit-03","difficulty":"core","unit":"Unit 03","originalSource":"quiz","type":"model"},{"id":"u03-q-x16","domain":"Systems and homeostasis","prompt":"A simple reflex arc is:","options":["Effector → motor → receptor","Hormone → artery → kidney","Muscle → bone → blood","Receptor → sensory → relay → motor → effector"],"answer":3,"explanation":"This is the correct pathway.","source":"unit-03","difficulty":"core","unit":"Unit 03","originalSource":"quiz","type":"model"},{"id":"u03-q-x17","domain":"Systems and homeostasis","prompt":"At a chemical synapse, neurotransmitters:","options":["Cross the gap and bind receptors","Become red cells","Move through bone","Replace DNA"],"answer":0,"explanation":"They bind receptors on the next cell.","source":"unit-03","difficulty":"core","unit":"Unit 03","originalSource":"quiz","type":"model"},{"id":"u03-q-x18","domain":"Systems and homeostasis","prompt":"Endocrine signals are often:","options":["Unable to affect cells","Slower to begin and longer lasting","Always faster and shorter","Carried only through neurones"],"answer":1,"explanation":"Hormonal signals often have slower onset and longer duration.","source":"unit-03","difficulty":"core","unit":"Unit 03","originalSource":"quiz","type":"model"},{"id":"u03-q-x19","domain":"Systems and homeostasis","prompt":"A first-line defense includes:","options":["Antibody production only","Fever only","Skin and mucus","Memory cells only"],"answer":2,"explanation":"Skin and mucus reduce entry.","source":"unit-03","difficulty":"core","unit":"Unit 03","originalSource":"quiz","type":"model"},{"id":"u03-q-x20","domain":"Systems and homeostasis","prompt":"Body systems are best described as:","options":["Independent systems","Only nervous regulation","Replacements for cells","Interdependent networks exchanging matter, energy, and information"],"answer":3,"explanation":"Systems interact continuously.","source":"unit-03","difficulty":"core","unit":"Unit 03","originalSource":"quiz","type":"model"},{"id":"u03-a-x01","domain":"Systems and homeostasis","prompt":"A regulated set range is:","options":["A functional interval around a target","A number that never changes","External temperature only","Unrelated to feedback"],"answer":0,"explanation":"Regulation usually maintains a range.","source":"unit-03","difficulty":"transfer","unit":"Unit 03","originalSource":"assessment","type":"model"},{"id":"u03-a-x02","domain":"Systems and homeostasis","prompt":"Body temperature rises. First event in a feedback model:","options":["Response ends","Receptors detect the change","Sweat evaporates","Temperature falls"],"answer":1,"explanation":"Detection comes first.","source":"unit-03","difficulty":"transfer","unit":"Unit 03","originalSource":"assessment","type":"model"},{"id":"u03-a-x03","domain":"Systems and homeostasis","prompt":"Negative feedback is stabilizing because:","options":["It destroys the receptor","It ignores change","It reduces the triggering deviation","It increases every deviation"],"answer":2,"explanation":"It opposes deviation.","source":"unit-03","difficulty":"transfer","unit":"Unit 03","originalSource":"assessment","type":"model"},{"id":"u03-a-x04","domain":"Systems and homeostasis","prompt":"Positive feedback is not usually long-term regulation because:","options":["It always lowers variables","It has no effectors","It prevents communication","It amplifies change until an endpoint"],"answer":3,"explanation":"It reinforces change.","source":"unit-03","difficulty":"transfer","unit":"Unit 03","originalSource":"assessment","type":"model"},{"id":"u03-a-x05","domain":"Systems and homeostasis","prompt":"Which chamber pumps systemic circulation?","options":["Left ventricle","Right atrium","Left atrium","Right ventricle"],"answer":0,"explanation":"The left ventricle pumps through the aorta.","source":"unit-03","difficulty":"transfer","unit":"Unit 03","originalSource":"assessment","type":"model"},{"id":"u03-a-x06","domain":"Systems and homeostasis","prompt":"Which vessel carries blood to lungs?","options":["Vena cava","Pulmonary artery","Pulmonary vein","Aorta"],"answer":1,"explanation":"The pulmonary artery carries blood to lungs.","source":"unit-03","difficulty":"transfer","unit":"Unit 03","originalSource":"assessment","type":"model"},{"id":"u03-a-x07","domain":"Systems and homeostasis","prompt":"Major capillary function:","options":["Produce enzymes","Store urine","Thin exchange surface","Generate brain impulses"],"answer":2,"explanation":"Capillaries support exchange.","source":"unit-03","difficulty":"transfer","unit":"Unit 03","originalSource":"assessment","type":"model"},{"id":"u03-a-x08","domain":"Systems and homeostasis","prompt":"Primary oxygen-transport component:","options":["Platelets","Plasma proteins only","White cells","Red cells with hemoglobin"],"answer":3,"explanation":"Hemoglobin carries oxygen.","source":"unit-03","difficulty":"transfer","unit":"Unit 03","originalSource":"assessment","type":"model"},{"id":"u03-a-x09","domain":"Systems and homeostasis","prompt":"Oxygen moves from alveoli to blood mainly because:","options":["A concentration gradient exists","Active transport pumps it","It becomes glucose","Walls are impermeable"],"answer":0,"explanation":"Diffusion follows the gradient.","source":"unit-03","difficulty":"transfer","unit":"Unit 03","originalSource":"assessment","type":"model"},{"id":"u03-a-x10","domain":"Systems and homeostasis","prompt":"Which reduces gas exchange efficiency?","options":["Continuous blood flow","Increased diffusion distance","Maintaining a gradient","Large surface area"],"answer":1,"explanation":"Longer distance slows diffusion.","source":"unit-03","difficulty":"transfer","unit":"Unit 03","originalSource":"assessment","type":"model"},{"id":"u03-a-x11","domain":"Systems and homeostasis","prompt":"Pulse rises from 72 to 108. Percent increase:","options":["72%","150%","50%","36%"],"answer":2,"explanation":"36/72 × 100 = 50%.","source":"unit-03","difficulty":"transfer","unit":"Unit 03","originalSource":"assessment","type":"model"},{"id":"u03-a-x12","domain":"Systems and homeostasis","prompt":"Why not diagnose from one classroom pulse response?","options":["Heart rate never changes","Pulse has no information","Only exercise affects pulse","It has many sources of variation and is not a clinical evaluation"],"answer":3,"explanation":"One short observation is insufficient.","source":"unit-03","difficulty":"transfer","unit":"Unit 03","originalSource":"assessment","type":"model"},{"id":"u03-a-x13","domain":"Systems and homeostasis","prompt":"Which organ produces bile?","options":["Liver","Stomach","Pancreas","Small intestine"],"answer":0,"explanation":"The liver produces bile.","source":"unit-03","difficulty":"transfer","unit":"Unit 03","originalSource":"assessment","type":"model"},{"id":"u03-a-x14","domain":"Systems and homeostasis","prompt":"Bile helps fat digestion by:","options":["Producing insulin","Emulsifying fat to increase surface area","Converting fat to amino acids","Absorbing glucose"],"answer":1,"explanation":"Emulsification supports lipase action.","source":"unit-03","difficulty":"transfer","unit":"Unit 03","originalSource":"assessment","type":"model"},{"id":"u03-a-x15","domain":"Systems and homeostasis","prompt":"Absorbed glucose and amino acids leave villi mainly in:","options":["Ureters","Motor neurones","Blood capillaries","Alveoli"],"answer":2,"explanation":"Capillaries transport them.","source":"unit-03","difficulty":"transfer","unit":"Unit 03","originalSource":"assessment","type":"model"},{"id":"u03-a-x16","domain":"Systems and homeostasis","prompt":"Excretion differs from egestion because:","options":["Both mean urination","Egestion removes carbon dioxide","Excretion removes only feces","Excretion removes metabolic wastes; egestion removes undigested material"],"answer":3,"explanation":"The processes remove different materials.","source":"unit-03","difficulty":"transfer","unit":"Unit 03","originalSource":"assessment","type":"model"},{"id":"u03-a-x17","domain":"Systems and homeostasis","prompt":"Normally reabsorbed completely from filtrate:","options":["Glucose","Urea","All water","All sodium"],"answer":0,"explanation":"Glucose is normally reabsorbed.","source":"unit-03","difficulty":"transfer","unit":"Unit 03","originalSource":"assessment","type":"model"},{"id":"u03-a-x18","domain":"Systems and homeostasis","prompt":"Higher ADH causes:","options":["No filtration","More water reabsorption","Less water reabsorption","More glucose excretion"],"answer":1,"explanation":"ADH promotes water recovery.","source":"unit-03","difficulty":"transfer","unit":"Unit 03","originalSource":"assessment","type":"model"},{"id":"u03-a-x19","domain":"Systems and homeostasis","prompt":"Which conserves heat?","options":["Increased evaporation","Stopping muscle activity","Reduced skin blood flow and shivering","Sweating and increased skin flow"],"answer":2,"explanation":"These conserve and produce heat.","source":"unit-03","difficulty":"transfer","unit":"Unit 03","originalSource":"assessment","type":"model"},{"id":"u03-a-x20","domain":"Systems and homeostasis","prompt":"Sweating cools because:","options":["Sweat freezes blood","Sweat stops metabolism","Evaporation creates energy","Evaporation transfers thermal energy from skin"],"answer":3,"explanation":"Evaporation requires energy.","source":"unit-03","difficulty":"transfer","unit":"Unit 03","originalSource":"assessment","type":"model"},{"id":"u03-a-x21","domain":"Systems and homeostasis","prompt":"Which hormone raises low blood glucose?","options":["Glucagon","Insulin","ADH","Thyroxine"],"answer":0,"explanation":"Glucagon promotes glucose release.","source":"unit-03","difficulty":"transfer","unit":"Unit 03","originalSource":"assessment","type":"model"},{"id":"u03-a-x22","domain":"Systems and homeostasis","prompt":"Insulin and glucagon:","options":["Do not affect liver","Have opposing regulatory effects","Both always lower glucose","Are digestive enzymes"],"answer":1,"explanation":"They act antagonistically.","source":"unit-03","difficulty":"transfer","unit":"Unit 03","originalSource":"assessment","type":"model"},{"id":"u03-a-x23","domain":"Systems and homeostasis","prompt":"Brain and spinal cord form the:","options":["Endocrine system","Circulatory system","Central nervous system","Peripheral nervous system"],"answer":2,"explanation":"They form the CNS.","source":"unit-03","difficulty":"transfer","unit":"Unit 03","originalSource":"assessment","type":"model"},{"id":"u03-a-x24","domain":"Systems and homeostasis","prompt":"A receptor in a reflex pathway:","options":["Contracts as final effector","Produces urine","Transports oxygen","Detects stimulus and initiates signal"],"answer":3,"explanation":"Receptors detect change.","source":"unit-03","difficulty":"transfer","unit":"Unit 03","originalSource":"assessment","type":"model"},{"id":"u03-a-x25","domain":"Systems and homeostasis","prompt":"Only some cells respond to a hormone because:","options":["Only target cells have the receptor","Hormones cannot travel in blood","Every hormone enters every nucleus","Hormones are antibodies"],"answer":0,"explanation":"Receptors determine response.","source":"unit-03","difficulty":"transfer","unit":"Unit 03","originalSource":"assessment","type":"model"},{"id":"u03-a-x26","domain":"Systems and homeostasis","prompt":"Accurate comparison:","options":["Both are identical","Nervous signals are often rapid/targeted; endocrine signals slower/distributed","Endocrine signals travel through bone","Nervous signals never use chemicals"],"answer":1,"explanation":"The systems differ in route and timing.","source":"unit-03","difficulty":"transfer","unit":"Unit 03","originalSource":"assessment","type":"model"},{"id":"u03-a-x27","domain":"Systems and homeostasis","prompt":"Cells that can produce antibodies after activation:","options":["Platelets","Neurones","B lymphocytes and plasma-cell descendants","Red cells"],"answer":2,"explanation":"Activated B cells produce plasma cells.","source":"unit-03","difficulty":"transfer","unit":"Unit 03","originalSource":"assessment","type":"model"},{"id":"u03-a-x28","domain":"Systems and homeostasis","prompt":"Immune memory cells support:","options":["Oxygen transport","Starch digestion","Urine regulation","Faster later response to the same antigen"],"answer":3,"explanation":"Memory supports secondary responses.","source":"unit-03","difficulty":"transfer","unit":"Unit 03","originalSource":"assessment","type":"model"},{"id":"u03-a-x29","domain":"Systems and homeostasis","prompt":"Strong health evidence includes:","options":["Transparent methods, comparisons, and limitations","Dramatic headline","Testimonial only","Universal claim from one result"],"answer":0,"explanation":"Transparent methods support evaluation.","source":"unit-03","difficulty":"transfer","unit":"Unit 03","originalSource":"assessment","type":"evidence"},{"id":"u03-a-x30","domain":"Systems and homeostasis","prompt":"During exercise, oxygen delivery and carbon-dioxide removal directly require:","options":["Skin alone","Respiratory and circulatory systems","Digestive and skeletal only","Urinary and reproductive only"],"answer":1,"explanation":"These systems cooperate directly.","source":"unit-03","difficulty":"transfer","unit":"Unit 03","originalSource":"assessment","type":"model"},{"id":"u04-q-q01","domain":"Genetic information","prompt":"Which statement correctly relates a gene to DNA?","options":["A gene is a segment of DNA involved in a functional product or regulation.","A gene is a protein surrounding every chromosome.","A gene is the complete genome.","A gene is a whole cell."],"answer":0,"explanation":"A gene is a functional or regulatory DNA region.","source":"unit-04","difficulty":"core","unit":"Unit 04","originalSource":"quiz","type":"model"},{"id":"u04-q-q02","domain":"Genetic information","prompt":"An allele is:","options":["A complete chromosome set","A variant form of a gene","Any environmental influence","A type of cell division"],"answer":1,"explanation":"Alleles are variant forms of a gene.","source":"unit-04","difficulty":"core","unit":"Unit 04","originalSource":"quiz","type":"model"},{"id":"u04-q-q03","domain":"Cell cycle","prompt":"During which part of the cell cycle is DNA copied?","options":["G1 only","Mitosis after separation","S phase of interphase","Cytokinesis"],"answer":2,"explanation":"DNA replication occurs during S phase.","source":"unit-04","difficulty":"core","unit":"Unit 04","originalSource":"quiz","type":"model"},{"id":"u04-q-q04","domain":"Mitosis","prompt":"Mitosis followed by cytokinesis in a typical diploid body cell usually produces:","options":["One tetraploid cell","Two gametes","Four haploid cells","Two cells with the same chromosome number as the parent"],"answer":3,"explanation":"Chromosome number is maintained.","source":"unit-04","difficulty":"core","unit":"Unit 04","originalSource":"quiz","type":"concept"},{"id":"u04-q-q05","domain":"Differentiation","prompt":"Cells with similar DNA can have different functions mainly because:","options":["Different genes are expressed","DNA becomes a different chemical","Only nerve cells have genes","They lose all unused chromosomes"],"answer":0,"explanation":"Differential gene expression supports specialization.","source":"unit-04","difficulty":"core","unit":"Unit 04","originalSource":"quiz","type":"concept"},{"id":"u04-q-q06","domain":"Cell-cycle control","prompt":"A checkpoint can:","options":["Prevent every mutation","Delay division when problems are detected","Convert mitosis to meiosis","Repair every damaged cell"],"answer":1,"explanation":"Checkpoints monitor conditions but are imperfect.","source":"unit-04","difficulty":"core","unit":"Unit 04","originalSource":"quiz","type":"model"},{"id":"u04-q-q07","domain":"Reproduction","prompt":"Asexual offspring are generally:","options":["Unable to survive change","Produced from two parents","Very similar to one parent except for mutation and other changes","Always polyploid"],"answer":2,"explanation":"Asexual reproduction copies one parent's genetic information.","source":"unit-04","difficulty":"core","unit":"Unit 04","originalSource":"quiz","type":"concept"},{"id":"u04-q-q08","domain":"Meiosis","prompt":"Meiosis is a reduction division because:","options":["It removes all mutations","It shortens chromosomes","It blocks replication","It halves chromosome number"],"answer":3,"explanation":"Meiosis produces haploid cells.","source":"unit-04","difficulty":"core","unit":"Unit 04","originalSource":"quiz","type":"concept"},{"id":"u04-q-q09","domain":"Meiosis","prompt":"Homologous chromosomes are:","options":["A pair carrying corresponding genes, one from each parent","Two unrelated chromosomes","Bacterial plasmids","Identical sister chromatids"],"answer":0,"explanation":"Homologues carry corresponding loci and may have different alleles.","source":"unit-04","difficulty":"core","unit":"Unit 04","originalSource":"quiz","type":"concept"},{"id":"u04-q-q10","domain":"Variation","prompt":"Which process creates new allele combinations during meiosis?","options":["Translation","Crossing over","Cytokinesis only","Binary fission"],"answer":1,"explanation":"Crossing over recombines chromosome segments.","source":"unit-04","difficulty":"core","unit":"Unit 04","originalSource":"quiz","type":"concept"},{"id":"u04-q-q11","domain":"Variation","prompt":"Independent assortment refers to:","options":["Every gene moving independently even when linked","Asexual reproduction","Random orientation and separation of homologous pairs","DNA replication"],"answer":2,"explanation":"Pair orientation creates chromosome combinations.","source":"unit-04","difficulty":"core","unit":"Unit 04","originalSource":"quiz","type":"concept"},{"id":"u04-q-q12","domain":"Fertilization","prompt":"Fertilization restores:","options":["Four nuclei","A chromosome-free cell","The haploid number","The diploid number"],"answer":3,"explanation":"Gamete fusion restores diploidy.","source":"unit-04","difficulty":"core","unit":"Unit 04","originalSource":"quiz","type":"concept"},{"id":"u04-q-q13","domain":"Inheritance language","prompt":"A dominant allele is one that:","options":["Is expressed in a heterozygote under the model","Is healthier","Prevents mutation","Is most common"],"answer":0,"explanation":"Dominance describes heterozygous expression, not value.","source":"unit-04","difficulty":"core","unit":"Unit 04","originalSource":"quiz","type":"concept"},{"id":"u04-q-q14","domain":"Inheritance language","prompt":"Genotype refers to:","options":["Environment","The allele combination considered","The species","Observable trait only"],"answer":1,"explanation":"Genotype is the allele combination.","source":"unit-04","difficulty":"core","unit":"Unit 04","originalSource":"quiz","type":"concept"},{"id":"u04-q-q15","domain":"Probability","prompt":"For Aa × Aa, the probability of aa is:","options":["75%","0%","25%","50%"],"answer":2,"explanation":"One of four combinations is aa.","source":"unit-04","difficulty":"core","unit":"Unit 04","originalSource":"quiz","type":"quantitative"},{"id":"u04-q-q16","domain":"Probability","prompt":"After three dominant-phenotype offspring in Aa × Aa, the next offspring's probability of aa is:","options":["50%","100%","0%","25%"],"answer":3,"explanation":"Each event remains independent.","source":"unit-04","difficulty":"core","unit":"Unit 04","originalSource":"quiz","type":"quantitative"},{"id":"u04-q-q17","domain":"Non-simple inheritance","prompt":"Incomplete dominance commonly gives a heterozygote:","options":["An intermediate phenotype","No phenotype","Both alleles hidden","Double chromosome number"],"answer":0,"explanation":"The heterozygote is intermediate.","source":"unit-04","difficulty":"core","unit":"Unit 04","originalSource":"quiz","type":"concept"},{"id":"u04-q-q18","domain":"Non-simple inheritance","prompt":"Codominance means a heterozygote:","options":["Has one allele","Expresses both allele products","Expresses neither","Is always intermediate"],"answer":1,"explanation":"Both products are detectably expressed.","source":"unit-04","difficulty":"core","unit":"Unit 04","originalSource":"quiz","type":"concept"},{"id":"u04-q-q19","domain":"Mutation","prompt":"Which statement about mutation is correct?","options":["Replication errors never occur","Every mutation is harmful","Effects can be harmful, beneficial, or neutral","Only environment causes mutation"],"answer":2,"explanation":"Effects depend on context.","source":"unit-04","difficulty":"core","unit":"Unit 04","originalSource":"quiz","type":"concept"},{"id":"u04-q-q20","domain":"Trait expression","prompt":"Phenotype can reflect:","options":["No change through life","Identical outcomes in all clones","Genes alone","Genotype, environment, development, and chance"],"answer":3,"explanation":"Phenotype often reflects multiple influences.","source":"unit-04","difficulty":"core","unit":"Unit 04","originalSource":"quiz","type":"concept"},{"id":"u04-a-a01","domain":"Genetic information","prompt":"Which sequence is ordered largest to smaller?","options":["Genome → chromosome → gene → nucleotide","Chromosome → genome → nucleotide → gene","Nucleotide → genome → chromosome → gene","Gene → chromosome → genome → nucleotide"],"answer":0,"explanation":"A genome contains chromosomes, which contain genes built from nucleotides.","source":"unit-04","difficulty":"transfer","unit":"Unit 04","originalSource":"assessment","type":"model"},{"id":"u04-a-a02","domain":"Genetic information","prompt":"A chromosome is:","options":["An amino acid","A long DNA molecule associated with proteins","A complete organism","An ATP-making organelle"],"answer":1,"explanation":"Chromosomes package DNA.","source":"unit-04","difficulty":"transfer","unit":"Unit 04","originalSource":"assessment","type":"model"},{"id":"u04-a-a03","domain":"Genetic information","prompt":"Sister chromatids are:","options":["Gametes","Homologues from two parents","Replicated copies of one chromosome joined before separation","Unrelated genes"],"answer":2,"explanation":"They are replicated copies.","source":"unit-04","difficulty":"transfer","unit":"Unit 04","originalSource":"assessment","type":"model"},{"id":"u04-a-a04","domain":"Cell cycle","prompt":"Which occurs before mitosis?","options":["Gamete fusion","Homologue separation","Protein digestion","DNA replication and preparation"],"answer":3,"explanation":"Interphase prepares the cell.","source":"unit-04","difficulty":"transfer","unit":"Unit 04","originalSource":"assessment","type":"model"},{"id":"u04-a-a05","domain":"Cell cycle","prompt":"Cytokinesis is:","options":["Division of cytoplasm","DNA copying","Homologue pairing","Translation"],"answer":0,"explanation":"Cytokinesis separates cytoplasm.","source":"unit-04","difficulty":"transfer","unit":"Unit 04","originalSource":"assessment","type":"model"},{"id":"u04-a-a06","domain":"Mitosis","prompt":"Which process produces additional body cells for wound repair?","options":["Crossing over","Mitosis","Meiosis only","Fertilization"],"answer":1,"explanation":"Mitosis supports repair.","source":"unit-04","difficulty":"transfer","unit":"Unit 04","originalSource":"assessment","type":"concept"},{"id":"u04-a-a07","domain":"Mitosis","prompt":"Why are mitotic daughter cells not guaranteed identical in every respect?","options":["They receive different homologues","DNA is never copied","Mutation, cytoplasmic differences, and later expression","Mitosis halves chromosomes"],"answer":2,"explanation":"Real cells can differ despite high genetic similarity.","source":"unit-04","difficulty":"transfer","unit":"Unit 04","originalSource":"assessment","type":"concept"},{"id":"u04-a-a08","domain":"Differentiation","prompt":"Differentiation is:","options":["Loss of all shared DNA","Gamete fusion","Chromosome doubling every generation","Development of specialized structures and functions"],"answer":3,"explanation":"Differentiation creates specialized cell types.","source":"unit-04","difficulty":"transfer","unit":"Unit 04","originalSource":"assessment","type":"concept"},{"id":"u04-a-a09","domain":"Cell-cycle control","prompt":"Which statement about cancer is accurate?","options":["A broad group involving abnormal growth and multiple possible regulatory changes","Every fast-dividing cell is cancerous","Checkpoints always prevent it","One disease from one mutation"],"answer":0,"explanation":"Cancer is heterogeneous.","source":"unit-04","difficulty":"transfer","unit":"Unit 04","originalSource":"assessment","type":"model"},{"id":"u04-a-a10","domain":"Reproduction","prompt":"An advantage of asexual reproduction can be:","options":["Adaptation to every change","Rapid reproduction without finding a mate","Guaranteed high variation","Four gametes"],"answer":1,"explanation":"It can be rapid and one-parent.","source":"unit-04","difficulty":"transfer","unit":"Unit 04","originalSource":"assessment","type":"concept"},{"id":"u04-a-a11","domain":"Reproduction","prompt":"A potential advantage of sexual reproduction is:","options":["Removal of harmful alleles","Identical offspring","New genetic combinations","Always more offspring"],"answer":2,"explanation":"Sexual reproduction reshuffles alleles.","source":"unit-04","difficulty":"transfer","unit":"Unit 04","originalSource":"assessment","type":"concept"},{"id":"u04-a-a12","domain":"Meiosis","prompt":"What separates in meiosis I?","options":["Sister chromatids only","Genes from DNA","Ribosomes","Homologous chromosomes"],"answer":3,"explanation":"Homologues separate.","source":"unit-04","difficulty":"transfer","unit":"Unit 04","originalSource":"assessment","type":"concept"},{"id":"u04-a-a13","domain":"Meiosis","prompt":"What separates in meiosis II?","options":["Sister chromatids","Alleles","Gametes","Homologues"],"answer":0,"explanation":"Sister chromatids separate.","source":"unit-04","difficulty":"transfer","unit":"Unit 04","originalSource":"assessment","type":"concept"},{"id":"u04-a-a14","domain":"Meiosis","prompt":"A diploid organism has 8 chromosomes. A gamete has:","options":["2","4","8","16"],"answer":1,"explanation":"The haploid number is 4.","source":"unit-04","difficulty":"transfer","unit":"Unit 04","originalSource":"assessment","type":"concept"},{"id":"u04-a-a15","domain":"Variation","prompt":"Which creates variation without creating a new allele?","options":["A deletion","A replication error","Independent assortment","A substitution mutation"],"answer":2,"explanation":"It reshuffles existing alleles.","source":"unit-04","difficulty":"transfer","unit":"Unit 04","originalSource":"assessment","type":"concept"},{"id":"u04-a-a16","domain":"Variation","prompt":"Crossing over normally occurs between:","options":["Unrelated chromosomes only","Ribosomes","Gametes after fertilization","Non-sister chromatids of homologues"],"answer":3,"explanation":"Corresponding segments exchange.","source":"unit-04","difficulty":"transfer","unit":"Unit 04","originalSource":"assessment","type":"concept"},{"id":"u04-a-a17","domain":"Fertilization","prompt":"A zygote forms by:","options":["Fusion of haploid gametes","Body-cell replication","Chromatid separation","Budding"],"answer":0,"explanation":"Fertilization forms a zygote.","source":"unit-04","difficulty":"transfer","unit":"Unit 04","originalSource":"assessment","type":"concept"},{"id":"u04-a-a18","domain":"Inheritance language","prompt":"Which genotype is heterozygous?","options":["RR","Rr","rr","R"],"answer":1,"explanation":"Rr has two different alleles.","source":"unit-04","difficulty":"transfer","unit":"Unit 04","originalSource":"assessment","type":"concept"},{"id":"u04-a-a19","domain":"Inheritance language","prompt":"If R is dominant, which genotype has the recessive phenotype?","options":["RR only","Rr only","rr only","RR and Rr"],"answer":2,"explanation":"Only rr is recessive in this model.","source":"unit-04","difficulty":"transfer","unit":"Unit 04","originalSource":"assessment","type":"concept"},{"id":"u04-a-a20","domain":"Probability","prompt":"For Aa × aa, the expected heterozygous proportion is:","options":["3/4","0","1/4","1/2"],"answer":3,"explanation":"Half are Aa.","source":"unit-04","difficulty":"transfer","unit":"Unit 04","originalSource":"assessment","type":"quantitative"},{"id":"u04-a-a21","domain":"Probability","prompt":"For AA × aa, expected offspring are:","options":["All Aa","Half AA and half aa","One quarter aa","All AA"],"answer":0,"explanation":"Every offspring is Aa.","source":"unit-04","difficulty":"transfer","unit":"Unit 04","originalSource":"assessment","type":"quantitative"},{"id":"u04-a-a22","domain":"Probability","prompt":"In 200 expected offspring from Aa × Aa, expected aa count is:","options":["25","50","100","150"],"answer":1,"explanation":"One quarter of 200 is 50.","source":"unit-04","difficulty":"transfer","unit":"Unit 04","originalSource":"assessment","type":"quantitative"},{"id":"u04-a-a23","domain":"Probability","prompt":"Observed ratios often differ from expected ratios because:","options":["Alleles remember prior births","Ratios apply only to first offspring","Probability predicts long-run patterns, not exact small samples","Punnett squares stop meiosis"],"answer":2,"explanation":"Sampling variation occurs.","source":"unit-04","difficulty":"transfer","unit":"Unit 04","originalSource":"assessment","type":"quantitative"},{"id":"u04-a-a24","domain":"Non-simple inheritance","prompt":"RR red × WW white gives RW pink. This is:","options":["Codominance","Sex linkage","Complete dominance","Incomplete dominance"],"answer":3,"explanation":"The heterozygote is intermediate.","source":"unit-04","difficulty":"transfer","unit":"Unit 04","originalSource":"assessment","type":"concept"},{"id":"u04-a-a25","domain":"Non-simple inheritance","prompt":"Visible expression of both allele products is:","options":["Codominance","Incomplete dominance","Recessiveness","Independent assortment"],"answer":0,"explanation":"Both products are expressed.","source":"unit-04","difficulty":"transfer","unit":"Unit 04","originalSource":"assessment","type":"concept"},{"id":"u04-a-a26","domain":"Trait expression","prompt":"Genetically similar plants differ in height under different water levels. Best conclusion:","options":["They are different species","Environment influenced height","Their DNA must differ completely","Height has no genetic component"],"answer":1,"explanation":"Environment affected phenotype.","source":"unit-04","difficulty":"transfer","unit":"Unit 04","originalSource":"assessment","type":"concept"},{"id":"u04-a-a27","domain":"Mutation","prompt":"A skin-cell mutation is usually not inherited because:","options":["All somatic mutations are repaired","Only beneficial mutations inherit","It is outside the gamete-producing lineage","Skin cells lack DNA"],"answer":2,"explanation":"Germline location matters.","source":"unit-04","difficulty":"transfer","unit":"Unit 04","originalSource":"assessment","type":"concept"},{"id":"u04-a-a28","domain":"Mutation","prompt":"Which can create a new allele?","options":["Independent assortment alone","Fertilization alone","Cytokinesis alone","Mutation"],"answer":3,"explanation":"Mutation changes DNA sequence.","source":"unit-04","difficulty":"transfer","unit":"Unit 04","originalSource":"assessment","type":"concept"},{"id":"u04-a-a29","domain":"Evidence and ethics","prompt":"Appropriate school genetics practice is:","options":["Use fictional organisms and protect personal data","Infer paternity","Publish identifiable results","Require family medical histories"],"answer":0,"explanation":"Privacy is essential.","source":"unit-04","difficulty":"transfer","unit":"Unit 04","originalSource":"assessment","type":"evidence"},{"id":"u04-a-a30","domain":"Evidence and ethics","prompt":"Why is 'genetically superior' inaccurate for people?","options":["Only recessive alleles exist","Traits are complex and human value is not a biological ranking","All people have identical DNA","Genes never affect traits"],"answer":1,"explanation":"Genetics does not rank human worth.","source":"unit-04","difficulty":"transfer","unit":"Unit 04","originalSource":"assessment","type":"evidence"},{"id":"u05-q-q01","domain":"Ecological organization","prompt":"Which level includes interacting populations and abiotic conditions?","options":["Ecosystem","Species","Organism","Population"],"answer":0,"explanation":"An ecosystem includes a community and its abiotic environment.","source":"unit-05","difficulty":"core","unit":"Unit 05","originalSource":"quiz","type":"model"},{"id":"u05-q-q02","domain":"Niche","prompt":"A niche is best described as:","options":["Only the geographic location of an organism","The organism’s role, resource use, tolerances, timing, and interactions","A permanent population size","A fossil classification"],"answer":1,"explanation":"A niche is broader than habitat and includes ecological function and requirements.","source":"unit-05","difficulty":"core","unit":"Unit 05","originalSource":"quiz","type":"concept"},{"id":"u05-q-q03","domain":"Food webs","prompt":"What does an arrow from seed to mouse indicate?","options":["Both have identical roles","The seed hunts the mouse","Transfer of matter and energy from seed to mouse","The mouse produces the seed"],"answer":2,"explanation":"The consumer receives matter and chemical energy from the resource.","source":"unit-05","difficulty":"core","unit":"Unit 05","originalSource":"quiz","type":"model"},{"id":"u05-q-q04","domain":"Energy transfer","prompt":"If 5,000 kJ is available to one trophic level and 600 kJ to the next, efficiency is:","options":["83.3%","120%","8.3%","12%"],"answer":3,"explanation":"600 ÷ 5,000 × 100 = 12%.","source":"unit-05","difficulty":"core","unit":"Unit 05","originalSource":"quiz","type":"concept"},{"id":"u05-q-q05","domain":"Matter cycles","prompt":"Which process moves carbon from organisms to atmospheric carbon dioxide?","options":["Cellular respiration","Sedimentation only","Photosynthesis only","Nitrogen fixation"],"answer":0,"explanation":"Cellular respiration releases carbon dioxide.","source":"unit-05","difficulty":"core","unit":"Unit 05","originalSource":"quiz","type":"model"},{"id":"u05-q-q06","domain":"Biodiversity","prompt":"Two sites have the same species richness. Which additional information is needed to compare evenness?","options":["The age of the observer","Relative abundance of each species","Only the site names","Only total land area"],"answer":1,"explanation":"Evenness depends on how balanced species abundances are.","source":"unit-05","difficulty":"core","unit":"Unit 05","originalSource":"quiz","type":"model"},{"id":"u05-q-q07","domain":"Sampling","prompt":"Why must sampling effort be recorded in a biodiversity survey?","options":["It eliminates seasonal change","It replaces species identification","More effort can detect more organisms and affect comparisons","It proves every species was found"],"answer":2,"explanation":"Different effort can create apparent differences unrelated to actual diversity.","source":"unit-05","difficulty":"core","unit":"Unit 05","originalSource":"quiz","type":"evidence"},{"id":"u05-q-q08","domain":"Population density","prompt":"A count of 900 organisms across 60 hectares equals:","options":["54 per hectare","960 per hectare","10 per hectare","15 per hectare"],"answer":3,"explanation":"900 ÷ 60 = 15 per hectare.","source":"unit-05","difficulty":"core","unit":"Unit 05","originalSource":"quiz","type":"quantitative"},{"id":"u05-q-q09","domain":"Population models","prompt":"Why is carrying capacity not necessarily constant?","options":["It changes with environmental resources and pressures","It is set only by body size","It cannot be estimated","It equals zero for all predators"],"answer":0,"explanation":"Resources, habitat, climate, disease, interactions, and human actions change capacity.","source":"unit-05","difficulty":"core","unit":"Unit 05","originalSource":"quiz","type":"model"},{"id":"u05-q-q10","domain":"Interactions","prompt":"Which interaction is commonly represented +/+?","options":["Parasitism","Mutualism","Competition","Predation"],"answer":1,"explanation":"Mutualism describes an average benefit to both partners under stated conditions.","source":"unit-05","difficulty":"core","unit":"Unit 05","originalSource":"quiz","type":"model"},{"id":"u05-q-q11","domain":"Succession","prompt":"Secondary succession differs from primary succession because secondary succession usually begins with:","options":["Only volcanic rock and no soil","No matter present","Existing soil or biological legacies","No organisms ever returning"],"answer":2,"explanation":"Soil, seeds, roots, microbes, or survivors often persist after secondary disturbance.","source":"unit-05","difficulty":"core","unit":"Unit 05","originalSource":"quiz","type":"concept"},{"id":"u05-q-q12","domain":"Conservation","prompt":"Which conservation plan is strongest?","options":["One that hides uncertainty","One with no measurable target","One based only on popularity","One with a baseline, causal pressure, indicator, community rights, and revision rule"],"answer":3,"explanation":"Transparent goals, indicators, causes, rights, and adaptive revision support evaluation.","source":"unit-05","difficulty":"core","unit":"Unit 05","originalSource":"quiz","type":"model"},{"id":"u05-q-q14","domain":"Resistance","prompt":"Which statement about antimicrobial resistance is correct?","options":["A person’s body evolves resistance to the drug","Microbial populations can change in the frequency of resistant variants","Antibiotics intentionally teach bacteria","Resistance proves every historical ancestry claim"],"answer":1,"explanation":"Selection can increase resistant microbial variants; one example does not settle every origins claim.","source":"unit-05","difficulty":"core","unit":"Unit 05","originalSource":"quiz","type":"quantitative"},{"id":"u05-q-q15","domain":"Terminology","prompt":"In standard biology, macroevolution includes:","options":["Any personal worldview conclusion","Only changes within one lifetime","Speciation, extinction, and diversification at or above species level","An individual suddenly producing an unrelated organism"],"answer":2,"explanation":"Macroevolution is defined as patterns at or above the species level.","source":"unit-05","difficulty":"core","unit":"Unit 05","originalSource":"quiz","type":"concept"},{"id":"u05-q-q16","domain":"Species concepts","prompt":"Why can fossil species boundaries be uncertain?","options":["All fossils are identical","Geological context is irrelevant","Fossils never contain anatomy","Reproductive compatibility cannot usually be tested and variation may overlap"],"answer":3,"explanation":"Fossil classification relies on preserved anatomy and context rather than direct breeding tests.","source":"unit-05","difficulty":"core","unit":"Unit 05","originalSource":"quiz","type":"concept"},{"id":"u05-q-q17","domain":"Equid record","prompt":"Modern scientific diagrams of equid history are usually branching because:","options":["Multiple equid forms coexisted and many branches became extinct","Every fossil forms one direct ladder","Only one horse species ever existed","Branching eliminates uncertainty"],"answer":0,"explanation":"The evidence is interpreted as diversification with contemporaneous and extinct branches.","source":"unit-05","difficulty":"core","unit":"Unit 05","originalSource":"quiz","type":"concept"},{"id":"u05-q-q18","domain":"Evidence classification","prompt":"A fossil’s geological location is an observation; calling it a direct ancestor is:","options":["Another measurement","A historical inference","A unit conversion","A trophic role"],"answer":1,"explanation":"Ancestry is inferred from multiple lines of evidence.","source":"unit-05","difficulty":"core","unit":"Unit 05","originalSource":"quiz","type":"evidence"},{"id":"u05-q-q19","domain":"Worldviews","prompt":"How should student worldview positions be graded in this unit?","options":["By whether they adopt one required belief","By family religion","By accuracy, evidence classification, reasoning, source fairness, and respect","By majority vote"],"answer":2,"explanation":"The curriculum evaluates literacy and reasoning, not compelled belief.","source":"unit-05","difficulty":"core","unit":"Unit 05","originalSource":"quiz","type":"concept"},{"id":"u05-q-q20","domain":"Stewardship","prompt":"Which statement identifies possible common ground across origins views?","options":["Evidence should be hidden","Conservation requires agreement on every origins question","No responsibility for ecosystems","Protection of biodiversity and responsible stewardship can be supported from different worldviews"],"answer":3,"explanation":"People with different origins views can support evidence-based stewardship.","source":"unit-05","difficulty":"core","unit":"Unit 05","originalSource":"quiz","type":"concept"},{"id":"u05-a-a01","domain":"Organization","prompt":"Which sequence increases in ecological scale?","options":["Organism → population → community → ecosystem","Population → organism → ecosystem → community","Community → organism → population → ecosystem","Ecosystem → community → population → organism"],"answer":0,"explanation":"Individuals form populations; interacting populations form communities; communities plus abiotic environment form ecosystems.","source":"unit-05","difficulty":"transfer","unit":"Unit 05","originalSource":"assessment","type":"model"},{"id":"u05-a-a02","domain":"Observation and inference","prompt":"Which statement is a direct observation?","options":["The ecosystem will collapse","Twelve individuals were counted in a 10 m transect","The organism evolved this trait because it needed it","Shade caused the species decline"],"answer":1,"explanation":"A documented count is an observation; causal and historical statements are inferences.","source":"unit-05","difficulty":"transfer","unit":"Unit 05","originalSource":"assessment","type":"evidence"},{"id":"u05-a-a03","domain":"Habitat and niche","prompt":"Which statement correctly distinguishes habitat and niche?","options":["Niche is only body size","Habitat is a genome","Habitat is location; niche includes role and resource use","They are always identical"],"answer":2,"explanation":"Habitat describes where an organism lives; niche includes its ecological role and requirements.","source":"unit-05","difficulty":"transfer","unit":"Unit 05","originalSource":"assessment","type":"concept"},{"id":"u05-a-a04","domain":"Trophic roles","prompt":"Which is a detritivore?","options":["Oak tree","Green algae","Hawk","Earthworm ingesting leaf fragments"],"answer":3,"explanation":"A detritivore ingests detrital particles.","source":"unit-05","difficulty":"transfer","unit":"Unit 05","originalSource":"assessment","type":"concept"},{"id":"u05-a-a05","domain":"Food-web effects","prompt":"Why can removal of one species affect several others?","options":["Food webs contain direct and indirect interactions","Every species eats every other species","Energy cycles forever","Abiotic conditions never matter"],"answer":0,"explanation":"Networked interactions can transmit effects through several pathways.","source":"unit-05","difficulty":"transfer","unit":"Unit 05","originalSource":"assessment","type":"concept"},{"id":"u05-a-a06","domain":"Energy calculation","prompt":"A trophic level receives 320 kJ from a preceding level with 4,000 kJ. Efficiency is:","options":["6%","8%","12.5%","80%"],"answer":1,"explanation":"320 ÷ 4,000 × 100 = 8%.","source":"unit-05","difficulty":"transfer","unit":"Unit 05","originalSource":"assessment","type":"quantitative"},{"id":"u05-a-a08","domain":"Matter cycles","prompt":"Which process converts atmospheric nitrogen into biologically available forms?","options":["Respiration","Evaporation","Combustion","Nitrogen fixation"],"answer":3,"explanation":"Nitrogen fixation converts N₂ into compounds that enter biological cycles.","source":"unit-05","difficulty":"transfer","unit":"Unit 05","originalSource":"assessment","type":"model"},{"id":"u05-a-a09","domain":"Matter and energy","prompt":"Which statement is accurate?","options":["Matter cycles while energy flows through and dissipates","Neither crosses ecosystem boundaries","Energy cycles and matter flows one way","Both disappear"],"answer":0,"explanation":"Matter is conserved and recycled, while usable energy is dissipated.","source":"unit-05","difficulty":"transfer","unit":"Unit 05","originalSource":"assessment","type":"model"},{"id":"u05-a-a10","domain":"Diversity calculation","prompt":"A sample contains counts 4, 4, 4, and 4 for four species. Compared with counts 13, 1, 1, and 1, the first sample has:","options":["Lower richness","The same richness and greater evenness","No biodiversity","Fewer total organisms"],"answer":1,"explanation":"Both contain four species and 16 organisms, but the first is more even.","source":"unit-05","difficulty":"transfer","unit":"Unit 05","originalSource":"assessment","type":"quantitative"},{"id":"u05-a-a11","domain":"Survey design","prompt":"Which practice best protects threatened species?","options":["Publish exact nest coordinates","Handle every organism for identification","Avoid revealing precise sensitive locations and use non-contact records","Collect specimens without permits"],"answer":2,"explanation":"Location privacy and non-disturbance reduce risk.","source":"unit-05","difficulty":"transfer","unit":"Unit 05","originalSource":"assessment","type":"concept"},{"id":"u05-a-a12","domain":"Population change","prompt":"A population changes from 800 to 680. What is the percentage change?","options":["−12%","15%","85%","−15%"],"answer":3,"explanation":"(680−800) ÷ 800 × 100 = −15%.","source":"unit-05","difficulty":"transfer","unit":"Unit 05","originalSource":"assessment","type":"quantitative"},{"id":"u05-a-a13","domain":"Mark–recapture","prompt":"Which condition violates a simple mark–recapture assumption?","options":["Marked animals become much easier to capture than unmarked animals","The study interval is short","Marks remain identifiable","Marked individuals mix into the population"],"answer":0,"explanation":"Different capture probability biases the ratio.","source":"unit-05","difficulty":"transfer","unit":"Unit 05","originalSource":"assessment","type":"quantitative"},{"id":"u05-a-a14","domain":"Population growth","prompt":"Exponential growth assumes approximately:","options":["Only emigration","Constant proportional growth with no immediate resource limit","A fixed carrying capacity already reached","No births"],"answer":1,"explanation":"Exponential models approximate unrestricted proportional growth.","source":"unit-05","difficulty":"transfer","unit":"Unit 05","originalSource":"assessment","type":"quantitative"},{"id":"u05-a-a15","domain":"Predator–prey evidence","prompt":"A predator and prey time series shows opposite trends. What additional evidence strengthens a causal explanation?","options":["A personal preference","Removal of inconvenient years","Feeding records, prey survival, vegetation, disease, weather, and alternative-factor analysis","A single graph title"],"answer":2,"explanation":"Mechanistic and comparative evidence helps test causation.","source":"unit-05","difficulty":"transfer","unit":"Unit 05","originalSource":"assessment","type":"evidence"},{"id":"u05-a-a16","domain":"Interactions","prompt":"Which interaction is +/−?","options":["Competition","Commensalism","Mutualism","Predation"],"answer":3,"explanation":"A predator benefits while prey is harmed.","source":"unit-05","difficulty":"transfer","unit":"Unit 05","originalSource":"assessment","type":"model"},{"id":"u05-a-a17","domain":"Resilience","prompt":"Ecosystem resilience refers most closely to:","options":["Capacity to absorb disturbance while retaining or reorganizing key functions","Having the most species in every sample","Eliminating all fire","Never changing"],"answer":0,"explanation":"Resilience concerns persistence or recovery of functions despite change.","source":"unit-05","difficulty":"transfer","unit":"Unit 05","originalSource":"assessment","type":"model"},{"id":"u05-a-a18","domain":"Conservation evidence","prompt":"Which result is an outcome rather than a projection?","options":["A proposal promises recovery","A monitored population increased from 200 to 260 after intervention, with stated method","A slogan says the plan will work","A model predicts a 20% increase"],"answer":1,"explanation":"A measured post-intervention record is an observed outcome, though causal evaluation still needs design and comparison.","source":"unit-05","difficulty":"transfer","unit":"Unit 05","originalSource":"assessment","type":"evidence"},{"id":"u05-a-a19","domain":"Selection","prompt":"Which statement avoids teleological language?","options":["The drug created only useful mutations","Bacteria became resistant because they wanted to survive","Antibiotic exposure favored resistant variants that left more descendants","Every bacterium intentionally changed its DNA"],"answer":2,"explanation":"Selection changes variant frequencies; it does not require purposeful mutation.","source":"unit-05","difficulty":"transfer","unit":"Unit 05","originalSource":"assessment","type":"concept"},{"id":"u05-a-a20","domain":"Variation","prompt":"Which process creates new alleles?","options":["Selection alone","Independent assortment alone","Migration alone","Mutation"],"answer":3,"explanation":"Mutation changes DNA sequence and can create a new allele.","source":"unit-05","difficulty":"transfer","unit":"Unit 05","originalSource":"assessment","type":"concept"},{"id":"u05-a-a21","domain":"Microevolution","prompt":"A measured allele-frequency shift across generations is commonly classified as:","options":["Microevolution","A theological proof","A fossil ancestor","No biological change"],"answer":0,"explanation":"Microevolution includes measurable inherited-frequency changes in populations.","source":"unit-05","difficulty":"transfer","unit":"Unit 05","originalSource":"assessment","type":"concept"},{"id":"u05-a-a22","domain":"Speciation","prompt":"Which provides direct evidence relevant to speciation in living populations?","options":["One individual changing species during life","Reduced interbreeding or reproductive compatibility between diverging populations","A drawing without data","A claim that no boundaries exist"],"answer":1,"explanation":"Reproductive isolation is central to many species concepts.","source":"unit-05","difficulty":"transfer","unit":"Unit 05","originalSource":"assessment","type":"evidence"},{"id":"u05-a-a23","domain":"Macroevolution definition","prompt":"Which statement is consistent with the standard biological use of macroevolution?","options":["It is identical to abiogenesis","It requires a sudden jump by one individual","It includes speciation and diversification across lineages","It means acquired traits during one lifetime"],"answer":2,"explanation":"Macroevolution refers to patterns at or above the species level and is not the origin of life.","source":"unit-05","difficulty":"transfer","unit":"Unit 05","originalSource":"assessment","type":"concept"},{"id":"u05-a-a24","domain":"Fossils","prompt":"Which statement about fossil evidence is accurate?","options":["Every fossil includes its family tree","Fossils cannot be measured","Fossil classifications never change","Fossils can preserve anatomy and context but rarely identify a direct parent–descendant pair"],"answer":3,"explanation":"Anatomy and context are observed; ancestry is reconstructed and classifications may be revised.","source":"unit-05","difficulty":"transfer","unit":"Unit 05","originalSource":"assessment","type":"evidence"},{"id":"u05-a-a25","domain":"Equids","prompt":"Why is a ladder model of horse evolution misleading?","options":["The record is interpreted as branching, with coexisting forms and extinct side branches","Modern horses have many functional toes","DNA proves every fossil is a parent","No equids existed"],"answer":0,"explanation":"Equid diversity is not a single uninterrupted march.","source":"unit-05","difficulty":"transfer","unit":"Unit 05","originalSource":"assessment","type":"model"},{"id":"u05-a-a26","domain":"Evidence levels","prompt":"Which sequence moves from most direct to most interpretive?","options":["Worldview conclusion → measurement → specimen","Specimen → measurement → classification → ancestry inference → worldview conclusion","Ancestry inference → specimen → measurement","Classification → specimen → observation"],"answer":1,"explanation":"Evidence should be separated from progressively broader interpretation.","source":"unit-05","difficulty":"transfer","unit":"Unit 05","originalSource":"assessment","type":"evidence"},{"id":"u05-a-a28","domain":"Source evaluation","prompt":"How should an advocacy source be used?","options":["As proof that opposing evidence does not exist","Without identifying its perspective","As direct fossil evidence","As a primary source for what that organization argues, checked against underlying data"],"answer":3,"explanation":"Advocacy sources accurately document viewpoints, but scientific claims must be traced to data and methods.","source":"unit-05","difficulty":"transfer","unit":"Unit 05","originalSource":"assessment","type":"evidence"},{"id":"u05-a-a29","domain":"Fair assessment","prompt":"Which student response should receive the stronger score?","options":["One that accurately classifies evidence, fairly represents alternatives, and supports a reasoned conclusion","One that attacks another student’s faith","One that refuses to cite sources","One that repeats a preferred conclusion but misstates evidence"],"answer":0,"explanation":"Assessment is based on literacy, evidence, reasoning, and respectful representation.","source":"unit-05","difficulty":"transfer","unit":"Unit 05","originalSource":"assessment","type":"evidence"},{"id":"u05-a-a30","domain":"Stewardship","prompt":"A strong stewardship proposal includes:","options":["A hidden decision process","Target, baseline, action, indicator, community consideration, uncertainty, and revision rule","Only a moral slogan","No monitoring"],"answer":1,"explanation":"A testable and accountable plan defines evidence, action, rights, and adaptation.","source":"unit-05","difficulty":"transfer","unit":"Unit 05","originalSource":"assessment","type":"concept"},{"id":"u06-q-q01","domain":"Matter","prompt":"Which statement distinguishes an element from a compound?","options":["An element contains one type of atom; a compound contains elements chemically combined in fixed proportions","Compounds cannot be pure","Elements always separate physically","An element contains one proton only"],"answer":0,"explanation":"Elements have one atomic number; compounds have bonded elements in fixed ratios.","source":"unit-06","difficulty":"core","unit":"Unit 06","originalSource":"quiz","type":"concept"},{"id":"u06-q-q02","domain":"Atomic model","prompt":"Rutherford’s scattering evidence most directly supported:","options":["Atoms are indivisible spheres","Positive charge and most mass are concentrated in a small nucleus","Electrons are positive","Atoms contain no empty space"],"answer":1,"explanation":"Rare strong deflections supported a small dense positive nucleus.","source":"unit-06","difficulty":"core","unit":"Unit 06","originalSource":"quiz","type":"evidence"},{"id":"u06-q-q03","domain":"Particles","prompt":"Which particle has relative charge 0 and relative mass about 1?","options":["Ion","Electron","Neutron","Proton"],"answer":2,"explanation":"A neutron is neutral and has mass close to one atomic mass unit.","source":"unit-06","difficulty":"core","unit":"Unit 06","originalSource":"quiz","type":"concept"},{"id":"u06-q-q04","domain":"Atomic number","prompt":"An atom with 15 protons is always:","options":["Sulfur","Silicon","Carbon","Phosphorus"],"answer":3,"explanation":"Atomic number 15 identifies phosphorus.","source":"unit-06","difficulty":"core","unit":"Unit 06","originalSource":"quiz","type":"concept"},{"id":"u06-q-q05","domain":"Mass number","prompt":"An isotope has 17 protons and 20 neutrons. Its mass number is:","options":["37","3","17","20"],"answer":0,"explanation":"Mass number = 17 + 20 = 37.","source":"unit-06","difficulty":"core","unit":"Unit 06","originalSource":"quiz","type":"concept"},{"id":"u06-q-q06","domain":"Charge","prompt":"A calcium atom loses two electrons. The ion has charge:","options":["1+","2+","2−","1−"],"answer":1,"explanation":"Losing two electrons gives 2+.","source":"unit-06","difficulty":"core","unit":"Unit 06","originalSource":"quiz","type":"concept"},{"id":"u06-q-q07","domain":"Isotopes","prompt":"Which pair represents isotopes of the same element?","options":["³⁵Cl and ⁴⁰Ar","¹H and ⁴He","¹²C and ¹⁴C","²³Na and ²⁴Mg"],"answer":2,"explanation":"Both carbon atoms have six protons.","source":"unit-06","difficulty":"core","unit":"Unit 06","originalSource":"quiz","type":"concept"},{"id":"u06-q-q08","domain":"Atomic weight","prompt":"A weighted atomic mass must use:","options":["Atomic number divided by neutrons","Electron number plus charge","Only the largest mass number","Isotope mass multiplied by fractional abundance, summed"],"answer":3,"explanation":"Relative atomic mass is an abundance-weighted mean.","source":"unit-06","difficulty":"core","unit":"Unit 06","originalSource":"quiz","type":"concept"},{"id":"u06-q-q09","domain":"Shells","prompt":"Which is the shell configuration of calcium?","options":["2,8,8,2","2,8,10","2,8,7,3","20"],"answer":0,"explanation":"Twenty electrons distribute as 2,8,8,2.","source":"unit-06","difficulty":"core","unit":"Unit 06","originalSource":"quiz","type":"concept"},{"id":"u06-q-q10","domain":"Valence","prompt":"Which element has seven outer-shell electrons?","options":["Magnesium","Chlorine","Argon","Sodium"],"answer":1,"explanation":"Chlorine is Group 17.","source":"unit-06","difficulty":"core","unit":"Unit 06","originalSource":"quiz","type":"concept"},{"id":"u06-q-q11","domain":"Period","prompt":"An element with configuration 2,8,3 is in which period?","options":["1","2","3","13"],"answer":2,"explanation":"Three occupied shells place it in Period 3.","source":"unit-06","difficulty":"core","unit":"Unit 06","originalSource":"quiz","type":"concept"},{"id":"u06-q-q12","domain":"Group","prompt":"Which pair belongs to Group 2?","options":["F and Cl","Ne and Ar","Li and Na","Be and Mg"],"answer":3,"explanation":"Beryllium and magnesium have two outer electrons.","source":"unit-06","difficulty":"core","unit":"Unit 06","originalSource":"quiz","type":"concept"},{"id":"u06-q-q13","domain":"Periodic order","prompt":"What uniquely fixes an element’s position in atomic-number order?","options":["Proton count","Average neutron count","Physical state","Discovery date"],"answer":0,"explanation":"Proton count is atomic number.","source":"unit-06","difficulty":"core","unit":"Unit 06","originalSource":"quiz","type":"concept"},{"id":"u06-q-q14","domain":"Group 1","prompt":"Which is the safest way to study alkali-metal reactivity?","options":["Put potassium in water at home","Use verified datasets or a qualified recorded demonstration","Touch sodium","Mix unknown metals with acid"],"answer":1,"explanation":"Reactive alkali metals require specialist controls.","source":"unit-06","difficulty":"core","unit":"Unit 06","originalSource":"quiz","type":"concept"},{"id":"u06-q-q15","domain":"Group 17","prompt":"Which statement is accurate for halogens down Group 17?","options":["They form 2+ ions","Outer-electron number increases","Reactivity generally decreases","All are gases"],"answer":2,"explanation":"Reactivity generally decreases down the group.","source":"unit-06","difficulty":"core","unit":"Unit 06","originalSource":"quiz","type":"concept"},{"id":"u06-q-q16","domain":"Noble gases","prompt":"Which element has a filled second shell?","options":["Sodium","Oxygen","Fluorine","Neon"],"answer":3,"explanation":"Neon has 2,8.","source":"unit-06","difficulty":"core","unit":"Unit 06","originalSource":"quiz","type":"concept"},{"id":"u06-q-q17","domain":"Spectra","prompt":"Why can line spectra help identify elements?","options":["Each element has characteristic allowed energy differences","All emit the same wavelengths","Spectra show neutron positions","Only compounds emit light"],"answer":0,"explanation":"Characteristic energy differences produce characteristic lines.","source":"unit-06","difficulty":"core","unit":"Unit 06","originalSource":"quiz","type":"concept"},{"id":"u06-q-q18","domain":"Model limits","prompt":"Which statement is most responsible?","options":["The Bohr picture is exact","Models should be used within evidence and scale limitations","Diagrams are photographs","Electron paths are always exact"],"answer":1,"explanation":"Scientific models are useful representations with limits.","source":"unit-06","difficulty":"core","unit":"Unit 06","originalSource":"quiz","type":"model"},{"id":"u06-q-q19","domain":"Data","prompt":"An atomic-weight interval for an element indicates:","options":["The table is unordered","Proton count varies","Normal materials can have isotope-composition variation","The element has no isotopes"],"answer":2,"explanation":"Natural isotope ratios can vary.","source":"unit-06","difficulty":"core","unit":"Unit 06","originalSource":"quiz","type":"concept"},{"id":"u06-q-q20","domain":"Prediction","prompt":"An element has two occupied shells and one outer electron. Which fits?","options":["Sodium","Magnesium","Fluorine","Lithium"],"answer":3,"explanation":"Lithium has configuration 2,1.","source":"unit-06","difficulty":"core","unit":"Unit 06","originalSource":"quiz","type":"concept"},{"id":"u06-a-a01","domain":"Classification","prompt":"Which sample is a compound?","options":["Pure sodium chloride","Air","Copper metal","Oxygen gas"],"answer":0,"explanation":"Sodium chloride contains elements chemically combined in a fixed ratio.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment","type":"concept"},{"id":"u06-a-a02","domain":"Atomic evidence","prompt":"Which observation led Thomson to infer negatively charged particles within atoms?","options":["Atoms were visible in a microscope","Cathode rays were deflected by electric and magnetic fields","Gold foil produced alpha particles","All gases had identical spectra"],"answer":1,"explanation":"Cathode-ray deflection supported negatively charged subatomic particles.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment","type":"evidence"},{"id":"u06-a-a03","domain":"Atomic evidence","prompt":"In Rutherford scattering, most alpha particles passed through foil. This supports the inference that atoms are:","options":["Made only of electrons","Without nuclei","Mostly empty space at that scale","Uniform solid spheres"],"answer":2,"explanation":"Most particles encountered no concentrated mass or charge.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment","type":"evidence"},{"id":"u06-a-a04","domain":"Model revision","prompt":"Why did atomic models change over time?","options":["Scientists agreed never to test them","The proton count changed historically","Models are personal opinions only","New evidence exposed limitations and supported revised models"],"answer":3,"explanation":"Scientific models are revised when new evidence requires better explanations.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment","type":"model"},{"id":"u06-a-a05","domain":"Particle charge","prompt":"Which set of relative charges is correct for proton, neutron, electron?","options":["+1, 0, −1","−1, 0, +1","+1, −1, 0","0, +1, −1"],"answer":0,"explanation":"Proton +1, neutron 0, electron −1.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment","type":"concept"},{"id":"u06-a-a06","domain":"Particle mass","prompt":"Which contributes least to an atom’s mass?","options":["Neutron","Electron","Nucleus","Proton"],"answer":1,"explanation":"Electron mass is much smaller than proton or neutron mass.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment","type":"concept"},{"id":"u06-a-a07","domain":"Composition","prompt":"A neutral atom contains 8 protons and 10 neutrons. Which statement is correct?","options":["It is oxygen-10 with 18 electrons","It is neon-18 with 10 electrons","It is oxygen-18 with 8 electrons","It is fluorine-18 with 8 electrons"],"answer":2,"explanation":"Atomic number 8 is oxygen; mass number 18; neutrality gives 8 electrons.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment","type":"concept"},{"id":"u06-a-a08","domain":"Ion charge","prompt":"A particle has 13 protons and 10 electrons. It is:","options":["Al³⁻","Ne³⁺","Mg²⁺","Al³⁺"],"answer":3,"explanation":"Atomic number 13 is aluminium; three fewer electrons gives 3+.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment","type":"concept"},{"id":"u06-a-a09","domain":"Nuclear notation","prompt":"In the notation ³⁹₁₉K, the lower number represents:","options":["Atomic number","Mass number","Neutron number","Electron charge"],"answer":0,"explanation":"The subscript is atomic number.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment","type":"concept"},{"id":"u06-a-a10","domain":"Isotopes","prompt":"Which property differs between neutral chlorine-35 and chlorine-37 atoms?","options":["Electron arrangement","Neutron number","Element identity","Proton number"],"answer":1,"explanation":"They differ in neutron number.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment","type":"concept"},{"id":"u06-a-a11","domain":"Weighted average","prompt":"An element has isotope masses 10 and 11 with abundances 20% and 80%. Its weighted mass is:","options":["10.2","10.5","10.8","21"],"answer":2,"explanation":"10(0.20)+11(0.80)=10.8.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment","type":"quantitative"},{"id":"u06-a-a12","domain":"Abundance","prompt":"Three isotope fractions are 0.79, 0.10, and 0.11. Their total is:","options":["1.10","79","0.90","1.00"],"answer":3,"explanation":"The fractions sum to 1.00.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment","type":"quantitative"},{"id":"u06-a-a13","domain":"Atomic weight","prompt":"Which statement about standard atomic weight is most accurate?","options":["It may be a weighted value or interval reflecting natural isotope composition","It equals the proton number","It is identical for every isotope","It is always a whole-number mass number"],"answer":0,"explanation":"Standard atomic weights summarize representative isotope masses and abundances.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment","type":"concept"},{"id":"u06-a-a14","domain":"Electron configuration","prompt":"Which configuration belongs to aluminium?","options":["2,7","2,8,3","2,8,2","2,8,4"],"answer":1,"explanation":"Aluminium has atomic number 13.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment","type":"concept"},{"id":"u06-a-a15","domain":"Ion configuration","prompt":"Which species has configuration 2,8?","options":["Cl⁻","K⁺","Na⁺","Na atom"],"answer":2,"explanation":"Na⁺ has 10 electrons; Cl⁻ and K⁺ have 18.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment","type":"concept"},{"id":"u06-a-a16","domain":"Period","prompt":"Which element is in Period 4 among the first 20?","options":["Sodium","Argon","Chlorine","Potassium"],"answer":3,"explanation":"Potassium has four occupied shells.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment","type":"concept"},{"id":"u06-a-a17","domain":"Group","prompt":"Which pair has related chemical properties because both have one outer electron?","options":["Li and K","O and Ne","Mg and Cl","C and Ar"],"answer":0,"explanation":"Lithium and potassium are Group 1.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment","type":"concept"},{"id":"u06-a-a18","domain":"Periodic history","prompt":"Mendeleev’s table was historically powerful partly because it:","options":["Rejected repeating properties","Left gaps and predicted properties of undiscovered elements","Was ordered by exact neutron count","Contained all 118 modern elements"],"answer":1,"explanation":"Its gaps enabled testable predictions.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment","type":"concept"},{"id":"u06-a-a19","domain":"Modern order","prompt":"Why is atomic number superior to relative atomic mass as the defining order?","options":["Neutrons determine chemistry alone","Atomic number is always larger","It uniquely identifies nuclear charge and resolves mass-order anomalies","Atomic mass is never measured"],"answer":2,"explanation":"Proton number fixes identity and corrects mass-order anomalies.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment","type":"concept"},{"id":"u06-a-a20","domain":"Across-period trend","prompt":"Across Period 3, which general change occurs?","options":["Atomic number decreases","Occupied shells increase from three to eight","All elements form +1 ions","Metallic character decreases toward nonmetals"],"answer":3,"explanation":"Metallic character generally declines across the period.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment","type":"concept"},{"id":"u06-a-a21","domain":"Group 1","prompt":"Which property generally increases from lithium to potassium?","options":["Reactivity with water","Melting point","Outer-electron count","Ion charge magnitude"],"answer":0,"explanation":"Group 1 reactivity generally increases down the group.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment","type":"concept"},{"id":"u06-a-a22","domain":"Group 17","prompt":"Which property generally decreases from fluorine to iodine?","options":["Density","Reactivity","Number of occupied shells","Atomic number"],"answer":1,"explanation":"Halogen reactivity generally decreases down the group.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment","type":"concept"},{"id":"u06-a-a23","domain":"Group 18","prompt":"Which is a noble gas?","options":["Potassium","Calcium","Argon","Chlorine"],"answer":2,"explanation":"Argon is Group 18.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment","type":"concept"},{"id":"u06-a-a24","domain":"Prediction","prompt":"An element in Group 2, Period 3 is:","options":["Calcium","Sodium","Aluminium","Magnesium"],"answer":3,"explanation":"Magnesium is in Period 3 and Group 2.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment","type":"concept"},{"id":"u06-a-a25","domain":"Prediction","prompt":"Which common ion is predicted for configuration 2,8,7?","options":["1− after gaining one electron","1+ after losing one proton","2− after losing two electrons","No possible ion"],"answer":0,"explanation":"The simple model predicts gain of one electron.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment","type":"concept"},{"id":"u06-a-a26","domain":"Spectra","prompt":"A line spectrum contains discrete wavelengths because:","options":["Visible light has no energy","Electron energies occur in allowed states and transitions have specific energy differences","The nucleus emits every wavelength","All atoms have one electron"],"answer":1,"explanation":"Specific transitions produce photons with specific energies.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment","type":"concept"},{"id":"u06-a-a27","domain":"Safety","prompt":"Which investigation is appropriate without a specialist laboratory?","options":["React potassium with water","Open a radioactive device","Analyze published emission spectra","Burn unknown salts indoors"],"answer":2,"explanation":"Published spectra can be analyzed safely.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment","type":"concept"},{"id":"u06-a-a28","domain":"Source quality","prompt":"Which source is strongest for a chlorine isotope calculation?","options":["An anonymous post","A movie prop","A product advertisement","A NIST isotope table with definitions and provenance"],"answer":3,"explanation":"A traceable reference database supplies definitions and provenance.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment","type":"evidence"},{"id":"u06-a-a29","domain":"Model limits","prompt":"Which statement avoids overstating a model?","options":["The shell model predicts useful outer-electron patterns but does not depict literal fixed paths","Electrons are colored balls exactly as shown","The nucleus is the same size as the diagram","A model cannot be revised"],"answer":0,"explanation":"The shell model is useful but not literal.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment","type":"model"},{"id":"u06-a-a30","domain":"Evidence reasoning","prompt":"A responsible periodic-trend conclusion should:","options":["Treat every group as identical","Use measured data, state the range, identify exceptions, and avoid claiming an absolute law","Discard values that do not fit","Use only one element"],"answer":1,"explanation":"Trend claims require defined scope and limitations.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment","type":"evidence"},{"unit":"Unit 00","domain":"Scientific Thinking & Evidence","prompt":"A student writes, ‘The liquid is cloudy, so a new substance definitely formed.’ Which statement is most scientifically defensible?","options":["Cloudiness is an observation; formation of a new substance is an inference requiring more evidence.","Cloudiness proves a chemical reaction occurred.","The statement contains only observations.","The liquid must be a mixture."],"answer":0,"explanation":"Cloudiness is directly observed; identifying a new substance requires additional evidence, so the claim must remain bounded.","id":"foundation-sf-a01","source":"unit-00","difficulty":"foundations","type":"evidence"},{"unit":"Unit 00","domain":"Scientific Thinking & Evidence","prompt":"Which question is most testable?","options":["Does light help plants?","How does 4, 8, or 12 hours of daily light affect mean seedling height after 14 days under otherwise matched conditions?","Are plants interesting?","Which plant is best?"],"answer":1,"explanation":"A testable question specifies a measurable independent variable, measurable outcome, timeframe, and controlled conditions.","id":"foundation-sf-a02","source":"unit-00","difficulty":"foundations","type":"evidence"},{"unit":"Unit 00","domain":"Scientific Thinking & Evidence","prompt":"Water temperature is changed and dissolving time is measured. Which pairing is correct?","options":["Independent: dissolving time; dependent: temperature","Independent: temperature; dependent: dissolving time","Independent: container; dependent: sugar mass","Independent: timer; dependent: room"],"answer":1,"explanation":"Temperature is deliberately changed, while dissolving time is measured as the response.","id":"foundation-sf-a03","source":"unit-00","difficulty":"foundations","type":"evidence"},{"unit":"Unit 00","domain":"Scientific Thinking & Evidence","prompt":"Which choice correctly distinguishes claim, evidence, and reasoning?","options":["Claim = data; evidence = opinion; reasoning = title","Claim answers the question; evidence is relevant data; reasoning explains why the evidence supports the claim using scientific ideas.","Claim and evidence are identical.","Reasoning is only a restatement of the evidence."],"answer":1,"explanation":"A claim answers the question, evidence supplies relevant observations or data, and reasoning links them using scientific principles.","id":"foundation-sf-a04","source":"unit-00","difficulty":"foundations","type":"evidence"},{"unit":"Unit 00","domain":"Measurement & Quantitative Reasoning","prompt":"Convert 2.75 m to centimeters.","options":["0.0275 cm","27.5 cm","275 cm","2750 cm"],"answer":2,"explanation":"One metre equals 100 centimetres, so 2.75 m × 100 = 275 cm.","id":"foundation-sf-b01","source":"unit-00","difficulty":"foundations","type":"quantitative"},{"unit":"Unit 00","domain":"Measurement & Quantitative Reasoning","prompt":"A sample has mass 63 g and volume 21 cm³. What is its density?","options":["3 g/cm³","42 g/cm³","84 g/cm³","1323 g/cm³"],"answer":0,"explanation":"Density = mass ÷ volume = 63 g ÷ 21 cm³ = 3 g/cm³.","id":"foundation-sf-b02","source":"unit-00","difficulty":"foundations","type":"quantitative"},{"unit":"Unit 00","domain":"Measurement & Quantitative Reasoning","prompt":"A temperature rises from 18 °C to 30 °C in 4 minutes. What is the average rate of temperature change?","options":["3 °C/min","4.5 °C/min","12 °C/min","48 °C/min"],"answer":0,"explanation":"Average rate = change ÷ time = (30−18) °C ÷ 4 min = 3 °C/min.","id":"foundation-sf-b03","source":"unit-00","difficulty":"foundations","type":"quantitative"},{"unit":"Unit 00","domain":"Measurement & Quantitative Reasoning","prompt":"A measurement rises from 50 to 65. Which pair is correct?","options":["Absolute change 15; percent change 30%","Absolute change 30; percent change 15%","Absolute change 15; percent change 15%","Absolute change 65; percent change 30%"],"answer":0,"explanation":"The absolute change is 15 and 15 ÷ 50 × 100 = 30%.","id":"foundation-sf-b04","source":"unit-00","difficulty":"foundations","type":"quantitative"},{"unit":"Unit 00","domain":"Tables, Graphs & Data","prompt":"For Trial Y values 10 at 0 min and 25 at 6 min, what is the average 0–6 minute rate?","options":["1.5 units/min","2.5 units/min","4.2 units/min","15 units/min"],"answer":1,"explanation":"Average rate = (25−10) units ÷ 6 min = 2.5 units/min.","id":"foundation-sf-c01","source":"unit-00","difficulty":"foundations","type":"concept"},{"unit":"Unit 00","domain":"Tables, Graphs & Data","prompt":"Which statement is a direct quantitative observation?","options":["Trial Y increased from 10 to 25 between 0 and 6 minutes.","Trial Y increased because the treatment accelerated a reaction.","The treatment must be better.","The mechanism is proven."],"answer":0,"explanation":"The numerical change from 10 to 25 is directly observed; the mechanism and value judgments are interpretations.","id":"foundation-sf-c02","source":"unit-00","difficulty":"foundations","type":"concept"},{"unit":"Unit 00","domain":"Tables, Graphs & Data","prompt":"A graph compares values 98 and 100 but begins the y-axis at 97. What is the best interpretation?","options":["The graph is automatically fraudulent.","The truncated axis can visually magnify a small numerical difference, so the scale and absolute values must be inspected.","All graphs must begin at zero.","Axis scale never affects visual interpretation."],"answer":1,"explanation":"A truncated axis can make a small numerical difference look visually large, so both scale and raw values must be read.","id":"foundation-sf-c03","source":"unit-00","difficulty":"foundations","type":"concept"},{"unit":"Unit 00","domain":"Tables, Graphs & Data","prompt":"Two groups have the same mean but one group has much greater spread. Which conclusion is best?","options":["The datasets are equivalent because the means match.","The mean alone is insufficient; variability also matters.","The group with greater spread must be wrong.","Spread never affects interpretation."],"answer":1,"explanation":"Equal means do not imply equal datasets; spread or variability can differ substantially.","id":"foundation-sf-c04","source":"unit-00","difficulty":"foundations","type":"concept"},{"unit":"Unit 00","domain":"Matter & Energy Foundations","prompt":"Which statement best distinguishes a compound from a mixture?","options":["A compound contains elements chemically combined in defined relationships; a mixture contains substances together without requiring chemical bonding between them.","A mixture is always one element.","A compound can be separated only by filtering.","There is no difference."],"answer":0,"explanation":"Compounds contain elements chemically combined in defined relationships, whereas mixtures contain substances together without requiring chemical bonding.","id":"foundation-sf-d01","source":"unit-00","difficulty":"foundations","type":"concept"},{"unit":"Unit 00","domain":"Matter & Energy Foundations","prompt":"Ice melts in a sealed container. Which statement is correct?","options":["A new substance forms.","Water molecules change identity.","Particle arrangement and motion change while chemical identity remains water.","Mass must decrease."],"answer":2,"explanation":"Melting changes particle arrangement and motion but does not change H₂O into a different substance.","id":"foundation-sf-d02","source":"unit-00","difficulty":"foundations","type":"concept"},{"unit":"Unit 00","domain":"Matter & Energy Foundations","prompt":"A sealed reaction vessel has mass 150.2 g before and 150.2 g after bubbles form. What does this support?","options":["Matter was created as gas.","Within measurement limits, total mass was conserved in the defined closed system.","Gas has no mass.","Energy became matter in ordinary classroom chemistry."],"answer":1,"explanation":"Equal total mass before and after in a closed system supports conservation of matter within measurement limits.","id":"foundation-sf-d03","source":"unit-00","difficulty":"foundations","type":"concept"},{"unit":"Unit 00","domain":"Matter & Energy Foundations","prompt":"Why can a warm bathtub contain more total thermal energy than a hotter cup of water?","options":["Temperature and thermal energy are always identical.","Total thermal energy depends on amount and material as well as temperature.","The bathtub must have a higher temperature.","Water in a cup has no thermal energy."],"answer":1,"explanation":"Temperature is not the same as total thermal energy; amount of matter and material properties also matter.","id":"foundation-sf-d04","source":"unit-00","difficulty":"foundations","type":"concept"},{"unit":"Unit 00","domain":"Cells, Scale & Biological Organization","prompt":"Which is a core idea of cell theory?","options":["All living organisms are composed of one or more cells.","Cells arise spontaneously from nonliving matter during normal growth.","Every cell has a cell wall.","All cells are identical."],"answer":0,"explanation":"Modern cell theory identifies cells as the basic structural units of living organisms.","id":"foundation-sf-e01","source":"unit-00","difficulty":"foundations","type":"model"},{"unit":"Unit 00","domain":"Cells, Scale & Biological Organization","prompt":"Which statement best describes diffusion?","options":["Particles intentionally seek low concentration.","Random molecular motion produces net movement from higher toward lower concentration when a pathway exists.","Particles stop moving at equilibrium.","Diffusion requires a pump in every case."],"answer":1,"explanation":"Random molecular motion creates net movement down a concentration gradient when a pathway is available.","id":"foundation-sf-e02","source":"unit-00","difficulty":"foundations","type":"model"},{"unit":"Unit 00","domain":"Cells, Scale & Biological Organization","prompt":"At dynamic equilibrium across a membrane, what happens?","options":["All particle motion stops.","Particles continue moving in both directions but there is no net change in distribution.","All particles move to one side.","The membrane disappears."],"answer":1,"explanation":"At dynamic equilibrium, particles continue moving both directions while the overall distribution remains stable.","id":"foundation-sf-e03","source":"unit-00","difficulty":"foundations","type":"model"},{"unit":"Unit 00","domain":"Cells, Scale & Biological Organization","prompt":"For cubes with side lengths 1, 2, and 3 units, SA:V changes 6:1 → 3:1 → 2:1. What is the biological implication?","options":["As size increases, exchange surface grows faster than volume.","As size increases, surface area relative to volume decreases, which can constrain exchange.","SA:V never affects biological exchange.","Larger cells always exchange faster."],"answer":1,"explanation":"Volume increases faster than surface area as size grows, so exchange surface per unit volume decreases.","id":"foundation-sf-e04","source":"unit-00","difficulty":"foundations","type":"model"},{"unit":"Unit 00","domain":"Systems, Models & Scientific Literacy","prompt":"Why does system boundary choice matter?","options":["It determines what is treated as inside/outside and which matter or energy transfers cross the boundary.","It changes the laws of nature.","It eliminates uncertainty.","It makes measurements unnecessary."],"answer":0,"explanation":"A system boundary defines what counts as inside, outside, and which matter or energy transfers cross the boundary.","id":"foundation-sf-f01","source":"unit-00","difficulty":"foundations","type":"model"},{"unit":"Unit 00","domain":"Systems, Models & Scientific Literacy","prompt":"Why is ‘exercise → breathing’ an incomplete causal model?","options":["Arrows never belong in science.","It names a relationship without identifying intermediate mechanisms or measurable state changes.","Exercise and breathing can never be related.","Causal models should contain only one node."],"answer":1,"explanation":"A useful causal model identifies intermediate mechanisms or measurable state changes rather than only naming endpoints.","id":"foundation-sf-f02","source":"unit-00","difficulty":"foundations","type":"model"},{"unit":"Unit 00","domain":"Systems, Models & Scientific Literacy","prompt":"What distinguishes feedback from a one-way causal chain?","options":["Feedback contains a later effect that returns to influence an earlier component or variable.","Feedback always has exactly two nodes.","Feedback is any correlation.","Feedback has no direction."],"answer":0,"explanation":"Feedback exists when a later effect returns to influence an earlier component or variable in the system.","id":"foundation-sf-f03","source":"unit-00","difficulty":"foundations","type":"model"},{"unit":"Unit 00","domain":"Systems, Models & Scientific Literacy","prompt":"Which statement correctly distinguishes S, P, and I in scientific notes?","options":["S = source-supported, P = paraphrase, I = student inference/synthesis.","S = speculation, P = proof, I = irrelevant.","All three mean quotation.","I statements never need evidence."],"answer":0,"explanation":"The notation distinguishes source-supported material, paraphrase, and student inference/synthesis so evidence and interpretation remain traceable.","id":"foundation-sf-f04","source":"unit-00","difficulty":"foundations","type":"model"},{"id":"u03-qa-q01","unit":"Unit 03","domain":"Thermoregulation data","prompt":"A synthetic thermoregulation model shows temperature falling from 37.8 °C to 37.2 °C over 12 minutes. What is the average rate of temperature change?","options":["−0.05 °C/min","+0.05 °C/min","−0.60 °C/min","+0.60 °C/min"],"answer":0,"explanation":"Average rate = (37.2−37.8)/12 = −0.60/12 = −0.05 °C/min.","source":"unit-03","difficulty":"transfer","type":"quantitative"},{"id":"u03-qa-q02","unit":"Unit 03","domain":"Circulation model","prompt":"A simplified cardiac-output model uses output = heart rate × volume pumped per beat. At 70 beats/min and 70 mL/beat, what output is predicted?","options":["4.9 L/min","0.49 L/min","49 L/min","140 mL/min"],"answer":0,"explanation":"70×70 = 4900 mL/min = 4.9 L/min.","source":"unit-03","difficulty":"transfer","type":"quantitative"},{"id":"u03-qa-q03","unit":"Unit 03","domain":"Feedback data","prompt":"A modeled regulated quantity decreases from 8.0 units to 5.6 units after a corrective response. What percent decrease occurred relative to the starting value?","options":["30%","24%","42.9%","70%"],"answer":0,"explanation":"Percent decrease = (8.0−5.6)/8.0 × 100 = 30%.","source":"unit-03","difficulty":"transfer","type":"quantitative"},{"id":"u03-qa-q04","unit":"Unit 03","domain":"Water balance","prompt":"A model organism takes in 2.1 L of water-equivalent input and loses 1.6 L over the same interval. What is the net balance?","options":["+0.5 L","−0.5 L","+3.7 L","−3.7 L"],"answer":0,"explanation":"Net balance = input − output = 2.1−1.6 = +0.5 L.","source":"unit-03","difficulty":"core","type":"quantitative"},{"id":"u03-qa-q05","unit":"Unit 03","domain":"Respiratory response","prompt":"A synthetic breathing-rate record rises from 12 breaths/min to 18 breaths/min over 3 minutes. What is the average change in breathing rate per minute?","options":["+2 breaths/min per min","+6 breaths/min per min","+10 breaths/min per min","−2 breaths/min per min"],"answer":0,"explanation":"Change is 6 breaths/min over 3 min, so average change rate is +2 breaths/min per minute.","source":"unit-03","difficulty":"transfer","type":"quantitative"},{"id":"u03-qa-q06","unit":"Unit 03","domain":"Thermal energy","prompt":"A simplified body-system model transfers thermal energy outward at an average rate of 120 J/s for 300 s. How much energy is transferred?","options":["36,000 J","420 J","2.5 J","0.40 J"],"answer":0,"explanation":"Energy = power × time = 120×300 = 36,000 J.","source":"unit-03","difficulty":"transfer","type":"quantitative"},{"id":"u03-ev-q01","unit":"Unit 03","domain":"Negative feedback evidence","prompt":"A regulated variable is disturbed above its normal range and then repeatedly moves back toward the original range without external adjustment. Which interpretation is best supported?","options":["The data are consistent with negative feedback.","The data prove there is no regulation.","The disturbance permanently changed the set point.","The variable must be controlled by one organ only."],"answer":0,"explanation":"Return toward the prior range after disturbance is evidence consistent with a negative-feedback model, though it does not identify every mechanism.","source":"unit-03","difficulty":"transfer","type":"evidence"},{"id":"u03-ev-q02","unit":"Unit 03","domain":"Controlled physiological comparison","prompt":"Students compare two synthetic datasets to test whether temperature affects response rate. Which design provides the strongest evidence?","options":["Keep all modeled conditions the same except temperature and repeat trials.","Change temperature, starting value, and sample size together.","Compare one warm trial with one unrelated cool trial.","Choose only trials that match the prediction."],"answer":0,"explanation":"Changing one target variable while controlling others and repeating trials best isolates the tested relationship.","source":"unit-03","difficulty":"transfer","type":"evidence"},{"id":"u03-ev-q03","unit":"Unit 03","domain":"Correlation and causation","prompt":"A class dataset shows that two physiological variables rise together during activity. What conclusion is most defensible from that pattern alone?","options":["The variables are associated in the observed dataset, but causation requires additional evidence.","One variable definitely causes the other.","Both variables are measurement errors.","The relationship must hold in every person and condition."],"answer":0,"explanation":"Correlation supports association, not a unique causal mechanism.","source":"unit-03","difficulty":"transfer","type":"evidence"},{"id":"u03-ev-q04","unit":"Unit 03","domain":"Model limitation","prompt":"A homeostasis diagram shows one sensor, one control center, and one effector. Real biological regulation uses several interacting signals. What should a student conclude?","options":["The diagram is a useful simplified model with stated limits.","The diagram is useless because it is simplified.","The real system must contain exactly three parts.","Any omitted pathway can be ignored in evidence analysis."],"answer":0,"explanation":"Scientific models can be useful while deliberately simplifying complex interacting systems.","source":"unit-03","difficulty":"core","type":"evidence"},{"id":"u03-ev-q05","unit":"Unit 03","domain":"Data quality","prompt":"Four repeated synthetic measurements are 72, 73, 72, and 95 under unchanged conditions. What is the best next step?","options":["Check the 95 value for a recording, method, or unusual-trial explanation before deciding whether to exclude it.","Delete 95 immediately because it is inconvenient.","Average only 72 and 73.","Assume 95 proves the model is false."],"answer":0,"explanation":"An apparent outlier should be investigated and documented rather than automatically deleted or accepted.","source":"unit-03","difficulty":"transfer","type":"evidence"},{"id":"u03-ev-q06","unit":"Unit 03","domain":"Physiological data ethics","prompt":"A class investigation uses personal physiological measurements. Which evidence practice is most appropriate?","options":["Use consent, minimize identifying information, and report aggregated or de-identified results where possible.","Post names beside every measurement so the dataset is easier to read.","Collect extra personal information in case it becomes useful later.","Treat health-related measurements as public because they were collected for science."],"answer":0,"explanation":"Ethical scientific practice protects privacy, uses consent, and limits collection and disclosure of personal data.","source":"unit-03","difficulty":"transfer","type":"evidence"}];
